insert into public.syllabus_editions (contest_name,role_name,contest_year,exam_board)
select 'Polícia Militar do Distrito Federal','Oficial Policial Militar – 2º Tenente',2025,'CEBRASPE'
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Militar do Distrito Federal' and role_name='Oficial Policial Militar – 2º Tenente' and contest_year=2025
);

-- Discipline breakdown derived from the prova's own area codes and section
-- headers (CG1A01..CG1A09 for P1, 001A01..001A10 for P2), not guessed.
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Militar do Distrito Federal' and role_name='Oficial Policial Militar – 2º Tenente' and contest_year=2025
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de texto, coesão, coerência, sintaxe e pontuação (itens 1-8).'),
  ('Língua Inglesa','Compreensão de texto em língua inglesa (itens 9-12).'),
  ('Legislação da PMDF','Estatuto dos Policiais Militares (Lei nº 7.289/1984), organização básica (Lei nº 12.086/2009, Decreto nº 10.443/2020), Lei Orgânica Nacional das PMs (Lei nº 14.751/2023) (itens 13-18).'),
  ('Realidade do Distrito Federal','Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE) e aspectos histórico-geográficos e políticos do DF (itens 19-24).'),
  ('Direitos Humanos','Direitos humanos na Constituição Federal de 1988 e entendimento do STF (itens 25-26).'),
  ('Segurança Pública','Políticas públicas de segurança, prevenção e repressão policial (itens 27-30).'),
  ('Criminologia','Criminologia geral e vitimologia, modelos de reação ao crime (itens 31-36).'),
  ('Raciocínio Lógico-Matemático','Resolução de problemas matemáticos aplicados (itens 37-40).'),
  ('Administração Pública','Funções administrativas e comportamento organizacional (itens 41-44).'),
  ('Direito Constitucional','Direitos e garantias fundamentais, remédios constitucionais (itens 45-49).'),
  ('Direito Administrativo','Princípios da administração pública, convênios e contratos de repasse (Decreto nº 11.531/2023) (itens 50-54).'),
  ('Direito Penal','Parte geral e especial do Código Penal, concurso de pessoas e de crimes (itens 55-59).'),
  ('Direito Processual Penal','Competência, inquérito policial, prisão (itens 60-64).'),
  ('Legislação Penal Especial','Lei Maria da Penha e demais leis penais extravagantes (itens 65-70).'),
  ('Direito Penal Militar','Crimes militares previstos no Código Penal Militar (itens 71-75).'),
  ('Direito Processual Penal Militar','Inquérito Policial Militar (IPM) e competência da Justiça Militar (Código de Processo Penal Militar) (itens 76-80).')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2025,1,$q$Língua Portuguesa$q$,$q$O objetivo central do texto CG1A1 é destacar a potencialidade da IA A na gestão urbana. B na segurança. C no mercado de varejo. D na prevenção de ataques cibernéticos. E no monitoramento de comportamentos suspeitos.$q$,$q$O objetivo central do texto CG1A1 é destacar a potencialidade da IA A na gestão urbana. B na segurança. C no mercado de varejo. D na prevenção de ataques cibernéticos. E no monitoramento de comportamentos suspeitos. || JUSTIFICATIVAS: ||A|| - Incorreta. O contexto relativo à gestão urbana é secundário no texto, não sendo seu objetivo central.\*/ ||B|| - Correta. O uso da IA na segurança é o tema anunciado desde o primeiro período e reiterado ao longo de todo o texto, abrangendo tanto a segurança pública quanto a particular.\*/ ||C|| - Incorreta. O contexto relativo ao mercado de varejo é secundário no texto, não sendo seu objetivo central.\*/ ||D|| - Incorreta. O contexto relativo à prevenção de ataques cibernéticos é secundário no texto, não sendo seu objetivo central.\*/ ||E|| - Incorreta. O contexto relativo ao monitoramento de comportamentos é secundário no texto, e inclusive se insere no contexto principal, que é o da segurança.\*/$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,2,$q$Língua Portuguesa$q$,$q$De acordo com as ideias veiculadas no segundo parágrafo do texto CG1A1, o reconhecimento facial A é um recurso tecnológico que, no mercado de varejo, visa especificamente à prevenção de perdas. B representa o principal recurso da atualidade para a identificação de quadrilhas criminosas e o monitoramento de comportamentos suspeitos. C foi planejado, em princípio, para a aplicação na área de segurança pública. D facilita a fiscalização do desempenho dos trabalhadores do mercado de varejo durante horários de pico. E objetiva primordialmente a identificação de dados sobre o perfil do público no mercado de varejo.$q$,$q$De acordo com as ideias veiculadas no segundo parágrafo do texto CG1A1, o reconhecimento facial A é um recurso tecnológico que, no mercado de varejo, visa especificamente à prevenção de perdas. B representa o principal recurso da atualidade para a identificação de quadrilhas criminosas e o monitoramento de comportamentos suspeitos. C foi planejado, em princípio, para a aplicação na área de segurança pública. D facilita a fiscalização do desempenho dos trabalhadores do mercado de varejo durante horários de pico. E objetiva primordialmente a identificação de dados sobre o perfil do público no mercado de varejo. || JUSTIFICATIVAS: ||A|| - Incorreta. De acordo com o texto, o recurso “agora é aplicado no mercado de varejo, com funções que vão além da prevenção de perdas”. Ou seja, o recurso não visa especificamente à prevenção de perdas no mercado de varejo.\*/ ||B|| - Incorreta. O texto se limita a afirmar que o uso de reconhecimento facial “auxilia” nesses dois contextos: “O reconhecimento facial auxilia a identificação de quadrilhas e o monitoramento de comportamentos suspeitos”. Não há no texto a informação de que esse seja o principal recurso para a identificação de quadrilhas e o monitoramento de comportamentos suspeitos. \*/ ||C|| - Correta. De acordo com o texto, o reconhecimento facial foi “Inicialmente desenvolvido para a segurança pública”.\*/ ||D|| - Incorreta. A opção extrapola o conteúdo do texto. Sobre o assunto, o texto se limita a reproduzir a fala de Gustavo Maciel, que afirma que ‘As informações ajudam lojistas a planejar promoções, a organizar a exposição de produtos de acordo com o fluxo de clientes e até mesmo a otimizar o trabalho da equipe em horários de maior movimento’.\*/ ||E|| - Incorreta. Conforme o segundo parágrafo do texto, “o recurso agora é aplicado no mercado de varejo, com funções que vão além da prevenção de perdas. Ele auxilia a identificação de quadrilhas e o monitoramento de comportamentos suspeitos, mas também fornece dados sobre o perfil do público, como gênero e faixa etária.”. O texto relaciona as funções da IA no mercado de varejo, mas sem hierarquizá-las.\*/$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,3,$q$Língua Portuguesa$q$,$q$Com base no terceiro parágrafo do texto CG1A1, é correto concluir que as cidades inteligentes A já contam, ou deverão contar em breve, com iniciativas como monitoramento em tempo real, muralhas digitais e semáforos inteligentes. B são a promessa de solução mais eficaz para a questão da segurança pública na atualidade. C devem ser implementadas no Brasil ao longo do ano de 2026. D tornaram possível, de forma inédita, a conexão entre tecnologia e qualidade de vida. E se limitam a otimizar a gestão urbana.$q$,$q$Com base no terceiro parágrafo do texto CG1A1, é correto concluir que as cidades inteligentes A já contam, ou deverão contar em breve, com iniciativas como monitoramento em tempo real, muralhas digitais e semáforos inteligentes. B são a promessa de solução mais eficaz para a questão da segurança pública na atualidade. C devem ser implementadas no Brasil ao longo do ano de 2026. D tornaram possível, de forma inédita, a conexão entre tecnologia e qualidade de vida. E se limitam a otimizar a gestão urbana. || JUSTIFICATIVAS: ||A|| - Correta. Afirma-se no texto que “Em 2026, espera-se que iniciativas como monitoramento em tempo real, muralhas digitais e semáforos inteligentes se tornem cada vez mais comuns”.\*/ ||B|| - Incorreta. A informação extrapola o conteúdo do texto, que apenas afirma que as cidades inteligentes são outro dos principais cenários de aplicação da IA no Brasil.\*/ ||C|| - Incorreta. No texto, a afirmativa de que “espera-se que iniciativas como monitoramento em tempo real, muralhas digitais e semáforos inteligentes se tornem cada vez mais comuns” dá a entender que essas tecnologias (ou parte delas) já estão em uso no país.\*/ ||D|| - Incorreta. Segundo o texto, “O uso da IA em cidades inteligentes reforça a conexão entre tecnologia e qualidade de vida, criando espaços urbanos mais eficientes e resilientes”, ou seja, as cidades inteligentes reforçam essa relação, mas não são elas que a tornaram possível. \*/ ||E|| - Incorreta. Segundo o texto, o objetivo das cidades inteligentes é “melhorar a segurança pública e também otimizar a gestão urbana”, ou seja, não se limita a este último aspecto.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,4,$q$Língua Portuguesa$q$,$q$Cada uma das opções a seguir apresenta uma proposta de reescrita para o seguinte trecho do primeiro parágrafo do texto CG1A1: “a tendência segue em expansão, refletindo um mercado em constante adaptação”. Assinale a opção em que a proposta apresentada é gramaticalmente correta e está em conformidade com os sentidos originais do texto. A a tendência segue em expansão e reflete um mercado em constante adaptação B a tendência segue em expansão, por que reflete um mercado em constante adaptação C a tendência segue em expansão embora reflita um mercado em constante adaptação D a tendência segue em expansão, logo, reflete um mercado em constante adaptação E a tendência segue em expansão dado refletir um mercado em constante adaptação$q$,$q$Cada uma das opções a seguir apresenta uma proposta de reescrita para o seguinte trecho do primeiro parágrafo do texto CG1A1: “a tendência segue em expansão, refletindo um mercado em constante adaptação”. Assinale a opção em que a proposta apresentada é gramaticalmente correta e está em conformidade com os sentidos originais do texto. A a tendência segue em expansão e reflete um mercado em constante adaptação B a tendência segue em expansão, por que reflete um mercado em constante adaptação C a tendência segue em expansão embora reflita um mercado em constante adaptação D a tendência segue em expansão, logo, reflete um mercado em constante adaptação E a tendência segue em expansão dado refletir um mercado em constante adaptação || JUSTIFICATIVAS: ||A|| - Correta. No trecho destacado do texto, a oração iniciada pelo verbo refletir adiciona uma informação à oração anterior, assim como a proposta de alteração feita na opção.\*/ ||B|| - Incorreta. No trecho destacado do texto, a oração iniciada pelo verbo refletir não consiste em explicação ou causa da anterior, logo os sentidos do texto não seriam mantidos com a reescrita, além de o emprego de “por que” ser incorreto no contexto.\*/ ||C|| - Incorreta. No trecho destacado do texto, a oração iniciada pelo verbo refletir não exprime circunstância de concessão em relação à oração anterior. Logo, os sentidos do texto não seriam mantidos na reescrita.\*/ ||D|| - Incorreta. No trecho destacado do texto, a oração iniciada pelo verbo refletir não veicula conclusão em relação à oração anterior. Logo, os sentidos do texto não seriam mantidos na reescrita.\*/ ||E|| - Incorreta. No trecho destacado do texto, a oração iniciada pelo verbo refletir não consiste em explicação ou causa da anterior. Logo, os sentidos do texto não seriam mantidos na reescrita.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,5,$q$Língua Portuguesa$q$,$q$No trecho “O reconhecimento facial auxilia a identificação de quadrilhas e o monitoramento de comportamentos suspeitos, mas também fornece dados sobre o perfil do público” do texto CG1A1, a expressão “mas também” estabelece, com a oração que a precede, relação de A adição. B oposição. C explicação. D conclusão. E causa.$q$,$q$No trecho “O reconhecimento facial auxilia a identificação de quadrilhas e o monitoramento de comportamentos suspeitos, mas também fornece dados sobre o perfil do público” do texto CG1A1, a expressão “mas também” estabelece, com a oração que a precede, relação de A adição. B oposição. C explicação. D conclusão. E causa. || JUSTIFICATIVAS: ||A|| - Correta. A locução “mas também” indica adição de ideias. No trecho, afirma-se que o reconhecimento facial \[não só\] auxilia a identificação de quadrilhas e o monitoramento de comportamentos suspeitos, mas também fornece dados sobre o perfil do público. Nesse caso, por meio da expressão “mas também”, acrescenta-se uma das aplicações do reconhecimento facial.\*/ ||B|| - Incorreta. A locução “mas também” indica adição de ideias, e não oposição.\*/ ||C|| - Incorreta. A locução “mas também” indica adição de ideias, e não explicação.\*/ ||D|| - Incorreta. A locução “mas também” indica adição de ideias, e não conclusão. \*/ ||E|| - Incorreta. A locução “mas também” indica adição de ideias, e não causa.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,6,$q$Língua Portuguesa$q$,$q$No terceiro parágrafo do texto CG1A1, a partícula “se”, em sua primeira ocorrência no trecho “espera-se que iniciativas como monitoramento em tempo real, muralhas digitais e semáforos inteligentes se tornem cada vez mais comuns”, indica que A o verbo da primeira oração desse trecho está empregado na voz passiva. B o sujeito da primeira oração desse trecho se classifica gramaticalmente como indeterminado. C a primeira oração desse trecho não tem sujeito gramatical. D o verbo da primeira oração desse trecho está empregado como reflexivo. E o verbo da primeira oração desse trecho é pronominal.$q$,$q$No terceiro parágrafo do texto CG1A1, a partícula “se”, em sua primeira ocorrência no trecho “espera-se que iniciativas como monitoramento em tempo real, muralhas digitais e semáforos inteligentes se tornem cada vez mais comuns”, indica que A o verbo da primeira oração desse trecho está empregado na voz passiva. B o sujeito da primeira oração desse trecho se classifica gramaticalmente como indeterminado. C a primeira oração desse trecho não tem sujeito gramatical. D o verbo da primeira oração desse trecho está empregado como reflexivo. E o verbo da primeira oração desse trecho é pronominal. || JUSTIFICATIVAS: ||A|| - Correta. No caso, a partícula “se” é um pronome apassivador, indicando que a oração está na voz passiva sintética. O verbo “esperar” é transitivo direto e o sujeito da primeira oração é a segunda oração: \[“que iniciativas como monitoramento em tempo real (...) se tornem cada vez mais comuns”\]. \*/ ||B|| - Incorreta. O sujeito da primeira oração é a oração seguinte: \[“que iniciativas como monitoramento em tempo real (...) se tornem cada vez mais comuns”\].\*/ ||C|| - Incorreta. O verbo “esperar” é transitivo direto e pessoal, ou seja, a oração tem sujeito, sendo ele expresso pela oração seguinte: \[“que iniciativas como monitoramento em tempo real (...) se tornem cada vez mais comuns”\].\*/ ||D|| - Incorreta. No caso, a partícula “se” não é pronome reflexivo, mas pronome apassivador, indicando que a oração está na voz passiva sintética.\*/ ||E|| - Incorreta. No caso, a partícula “se” não é parte integrante do verbo, mas pronome apassivador, indicando que a oração está na voz passiva sintética.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,7,$q$Língua Portuguesa$q$,$q$No trecho “O uso da IA em cidades inteligentes reforça a conexão entre tecnologia e qualidade de vida” do texto CG1A1, a forma verbal “reforça” é empregada com o mesmo sentido de A provoca. B facilita. C gera. D possibilita. E intensifica.$q$,$q$No trecho “O uso da IA em cidades inteligentes reforça a conexão entre tecnologia e qualidade de vida” do texto CG1A1, a forma verbal “reforça” é empregada com o mesmo sentido de A provoca. B facilita. C gera. D possibilita. E intensifica. || JUSTIFICATIVAS: ||A|| - Incorreta. O verbo “provocar” tem sentido diverso do de “reforçar”.\*/ ||B|| - Incorreta. O verbo “facilitar” tem sentido diverso do de “reforçar”.\*/ ||C|| - Incorreta. O verbo “gerar” tem sentido diverso do de “reforçar”.\*/ ||D|| - Incorreta. O verbo “possibilitar” tem sentido diverso do de “reforçar”.\*/ ||E|| - Correta. Os verbos “intensificar” e “reforçar” têm sentidos semelhantes e ambos são adequados ao contexto apresentado.\*/$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,8,$q$Língua Portuguesa$q$,$q$No que diz respeito à pontuação, seriam mantidos a correção gramatical e o sentido do último parágrafo do texto CG1A1 caso fosse A inserida vírgula imediatamente após a sigla “IA” no trecho “As inovações impulsionadas pela IA estão remodelando o setor de segurança no Brasil”. B suprimida a vírgula após “Brasil” no trecho “As inovações impulsionadas pela IA estão remodelando o setor de segurança no Brasil, e abrangem desde soluções patrimoniais”. C inserida vírgula após o vocábulo “inteligentes” no trecho “Tecnologias como o reconhecimento facial, as mídias digitais e os sistemas inteligentes demonstram o potencial da IA”. D inserida vírgula após a palavra ‘recursos’ no segmento ‘o país avança na adoção de recursos que atendem às demandas’. E suprimida a vírgula após ‘protegido’ no segmento “‘preparam para um futuro ainda mais conectado e protegido’, conclui Maciel”.$q$,$q$No que diz respeito à pontuação, seriam mantidos a correção gramatical e o sentido do último parágrafo do texto CG1A1 caso fosse A inserida vírgula imediatamente após a sigla “IA” no trecho “As inovações impulsionadas pela IA estão remodelando o setor de segurança no Brasil”. B suprimida a vírgula após “Brasil” no trecho “As inovações impulsionadas pela IA estão remodelando o setor de segurança no Brasil, e abrangem desde soluções patrimoniais”. C inserida vírgula após o vocábulo “inteligentes” no trecho “Tecnologias como o reconhecimento facial, as mídias digitais e os sistemas inteligentes demonstram o potencial da IA”. D inserida vírgula após a palavra ‘recursos’ no segmento ‘o país avança na adoção de recursos que atendem às demandas’. E suprimida a vírgula após ‘protegido’ no segmento “‘preparam para um futuro ainda mais conectado e protegido’, conclui Maciel”. || JUSTIFICATIVAS: ||A|| - Incorreta. A vírgula sugerida estaria entre o sujeito da oração e seu predicado, o que contraria as normas gramaticais.\*/ ||B|| - Correta. O emprego de vírgula entre orações coordenadas ligadas por meio da conjunção “e” é facultativo, segundo as regras de pontuação, conforme a pausa que se confere à leitura. \*/ ||C|| - Incorreta. A vírgula sugerida não se justifica com base nas regras gramaticais, pois separaria indevidamente o sujeito e o predicado da oração. \*/ ||D|| - Incorreta. A vírgula sugerida alteraria de restritiva para explicativa a oração iniciada pelo vocábulo ‘que’, o que alteraria o sentido do texto.\*/ ||E|| - Incorreta. A vírgula empregada separa uma citação direta da voz do narrador do texto, logo não pode ser omitida, segundo as regras de pontuação.\*/ Text CG1A7 The United Kingdom (UK) government is developing a “murder prediction” programme which it hopes can use personal data of those known to the authorities to identify the people most likely to become killers. Researchers are alleged to be using algorithms to analyse the information of thousands of people, including victims of crime, as they try to identify those at greatest risk of committing serious violent offences. The Ministry of Justice (MoJ) says the scheme will “review offender characteristics that increase the risk of committing homicide” and “explore alternative and innovative data science techniques to risk assessment of homicide”. The project would “provide evidence towards improving risk assessment of serious crime and ultimately contribute to protecting the public via better analysis”, a spokesperson added. The MoJ hopes the project will help boost public safety, but campaigners have called it “chilling and dystopian”. Sofia Lyall, a researcher for Statewatch, the pressure group that discovered the existence of the project, said: “Time and again, research shows that algorithmic systems for ‘predicting’ crime are inherently flawed. This latest model \[…\] will reinforce and magnify the structural discrimination underpinning the criminal legal system.” “Like other systems of its kind, it will code in bias towards racialised and low-income communities. Building an automated tool to profile people as violent criminals is deeply wrong, and using such sensitive data on mental health, addiction and disability is highly intrusive and alarming,” added Lyall. Internet: \<https://www.theguardian.com/uk-news\> (adapted).$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,9,$q$Língua Inglesa$q$,$q$In the fragment “The MoJ hopes the project will help boost public safety, but campaigners have called it ‘chilling and dystopian’.” (third paragraph of text CG1A7), it can be correctly concluded that the pronoun “it” refers to A “The MoJ”. B “the project”. C “boost”. D “public safety”. E “campaigners”.$q$,$q$In the fragment “The MoJ hopes the project will help boost public safety, but campaigners have called it ‘chilling and dystopian’.” (third paragraph of text CG1A7), it can be correctly concluded that the pronoun “it” refers to A “The MoJ”. B “the project”. C “boost”. D “public safety”. E “campaigners”. || JUSTIFICATIVAS: ||A|| - Incorreta. No excerto “The MoJ hopes the project will help boost public safety, but campaigners have called it ‘chilling and dystopian’”, “it” é um pronome pessoal de terceira pessoa do singular que retoma (ou substitui) um substantivo (ou expressão nominal) mencionado anteriormente no período. De imediato, verifica-se que “it” não poderia estar se referindo nem a “boost”, por ser este um verbo não substantivado nem a “campaigners”, por ser este um substantivo plural, que exigiria o uso de “them”. Além disso, verifica-se que os adjetivos que qualificam o substantivo retomado por “it” – “assustador” e “distópico” – têm conotação negativa. Haja vista que, como se pode depreender do conjunto do texto, as referências depreciativas dos ativistas remetem diretamente ao novo programa (também referido como projeto), conclui-se que “it” se refere a “the project”, e não a “The MoJ” ou a “public safety”. \*/ ||B|| - Correta. No excerto “The MoJ hopes the project will help boost public safety, but campaigners have called it ‘chilling and dystopian’”, “it” é um pronome pessoal de terceira pessoa do singular que retoma (ou substitui) um substantivo (ou expressão nominal) mencionado anteriormente no período. De imediato, verifica-se que “it” não poderia estar se referindo nem a “boost”, por ser este um verbo não substantivado nem a “campaigners”, por ser este um substantivo plural, que exigiria o uso de “them”. Além disso, verifica-se que os adjetivos que qualificam o substantivo retomado por “it” – “assustador” e “distópico” – têm conotação negativa. Haja vista que, como se pode depreender do conjunto do texto, as referências depreciativas dos ativistas remetem diretamente ao novo programa (também referido como projeto), conclui-se que “it” se refere a “the project”, e não a “The MoJ” ou a “public safety”.\*/ ||C|| - Incorreta. No excerto “The MoJ hopes the project will help boost public safety, but campaigners have called it ‘chilling and dystopian’”, “it” é um pronome pessoal de terceira pessoa do singular que retoma (ou substitui) um substantivo (ou expressão nominal) mencionado anteriormente no período. De imediato, verifica-se que “it” não poderia estar se referindo nem a “boost”, por ser este um verbo não substantivado nem a “campaigners”, por ser este um substantivo plural, que exigiria o uso de “them”. Além disso, verifica-se que os adjetivos que qualificam o substantivo retomado por “it” – “assustador” e “distópico” – têm conotação negativa. Haja vista que, como se pode depreender do conjunto do texto, as referências depreciativas dos ativistas remetem diretamente ao novo programa (também referido como projeto), conclui-se que “it” se refere a “the project”, e não a “The MoJ” ou a “public safety”.\*/ ||D|| - Incorreta. No excerto “The MoJ hopes the project will help boost public safety, but campaigners have called it ‘chilling and dystopian’”, “it” é um pronome pessoal de terceira pessoa do singular que retoma (ou substitui) um substantivo (ou expressão nominal) mencionado anteriormente no período. De imediato, verifica-se que “it” não poderia estar se referindo nem a “boost”, por ser este um verbo não substantivado nem a “campaigners”, por ser este um substantivo plural, que exigiria o uso de “them”. Além disso, verifica-se que os adjetivos que qualificam o substantivo retomado por “it” – “assustador” e “distópico” – têm conotação negativa. Haja vista que, como se pode depreender do conjunto do texto, as referências depreciativas dos ativistas remetem diretamente ao novo programa (também referido como projeto), conclui-se que “it” se refere a “the project”, e não a “The MoJ” ou a “public safety”.\*/ ||E|| - Incorreta. No excerto “The MoJ hopes the project will help boost public safety, but campaigners have called it ‘chilling and dystopian’”, “it” é um pronome pessoal de terceira pessoa do singular que retoma (ou substitui) um substantivo (ou expressão nominal) mencionado anteriormente no período. De imediato, verifica-se que “it” não poderia estar se referindo nem a “boost”, por ser este um verbo não substantivado nem a “campaigners”, por ser este um substantivo plural, que exigiria o uso de “them”. Além disso, verifica-se que os adjetivos que qualificam o substantivo retomado por “it” – “assustador” e “distópico” – têm conotação negativa. Haja vista que, como se pode depreender do conjunto do texto, as referências depreciativas dos ativistas remetem diretamente ao novo programa (também referido como projeto), conclui-se que “it” se refere a “the project”, e não a “The MoJ” ou a “public safety”.\*/$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,10,$q$Língua Inglesa$q$,$q$Based on the information provided in text CG1A7 about the “‘murder prediction’ programme”, judge the following items. I The programme has been in use in the United Kingdom for at least a couple of years. II According to advocates of the programme in the UK government, one of its goals is to improve how the risk of serious crimes is assessed. III Opponents of the programme argue that it will increase the structural discrimination on which the UK criminal legal system is based. Choose the correct option. A Only item I is correct. B Only item II is correct. C Only items I and III are correct. D Only items II and III are correct. E All of the items are correct.$q$,$q$Based on the information provided in text CG1A7 about the “‘murder prediction’ programme”, judge the following items. I The programme has been in use in the United Kingdom for at least a couple of years. II According to advocates of the programme in the UK government, one of its goals is to improve how the risk of serious crimes is assessed. III Opponents of the programme argue that it will increase the structural discrimination on which the UK criminal legal system is based. Choose the correct option. A Only item I is correct. B Only item II is correct. C Only items I and III are correct. D Only items II and III are correct. E All of the items are correct. || JUSTIFICATIVAS: ||A|| - Incorreta. Apenas os itens II e III estão certos. O item I está errado. Consoante o primeiro parágrafo do texto, o programa encontra-se em fase de desenvolvimento, não estando ainda em uso. Adicionalmente, todo o restante do texto descreve as funcionalidades que o programa deverá apresentar no futuro, assim como os possíveis resultados — positivos e negativos — que poderão ser observados quando de sua efetiva implementação. O item II está certo. Consoante o segundo parágrafo do texto, de acordo com o Ministério da Justiça, defensor do programa, o projeto (o programa) forneceria subsídios ou elementos para aprimorar a avaliação de risco de crimes graves. O item III está certo. A afirmativa essencialmente reformula a declaração de Sofia Lyall, representante da organização Statewatch — crítica do programa —, apresentada no último período do quarto parágrafo do texto.\*/ ||B|| - Incorreta. Apenas os itens II e III estão certos. O item I está errado. Consoante o primeiro parágrafo do texto, o programa encontra-se em fase de desenvolvimento, não estando ainda em uso. Adicionalmente, todo o restante do texto descreve as funcionalidades que o programa deverá apresentar no futuro, assim como os possíveis resultados — positivos e negativos — que poderão ser observados quando de sua efetiva implementação. O item II está certo. Consoante o segundo parágrafo do texto, de acordo com o Ministério da Justiça, defensor do programa, o projeto (o programa) forneceria subsídios ou elementos para aprimorar a avaliação de risco de crimes graves. O item III está certo. A afirmativa essencialmente reformula a declaração de Sofia Lyall, representante da organização Statewatch — crítica do programa —, apresentada no último período do quarto parágrafo do texto.\*/ ||C|| - Incorreta. Apenas os itens II e III estão certos. O item I está errado. Consoante o primeiro parágrafo do texto, o programa encontra-se em fase de desenvolvimento, não estando ainda em uso. Adicionalmente, todo o restante do texto descreve as funcionalidades que o programa deverá apresentar no futuro, assim como os possíveis resultados — positivos e negativos — que poderão ser observados quando de sua efetiva implementação. O item II está certo. Consoante o segundo parágrafo do texto, de acordo com o Ministério da Justiça, defensor do programa, o projeto (o programa) forneceria subsídios ou elementos para aprimorar a avaliação de risco de crimes graves. O item III está certo. A afirmativa essencialmente reformula a declaração de Sofia Lyall, representante da organização Statewatch — crítica do programa —, apresentada no último período do quarto parágrafo do texto.\*/ ||D|| - Correta. Apenas os itens II e III estão certos. O item I está errado. Consoante o primeiro parágrafo do texto, o programa encontra-se em fase de desenvolvimento, não estando ainda em uso. Adicionalmente, todo o restante do texto descreve as funcionalidades que o programa deverá apresentar no futuro, assim como os possíveis resultados — positivos e negativos — que poderão ser observados quando de sua efetiva implementação. O item II está certo. Consoante o segundo parágrafo do texto, de acordo com o Ministério da Justiça, defensor do programa, o projeto (o programa) forneceria subsídios ou elementos para aprimorar a avaliação de risco de crimes graves. O item III está certo. A afirmativa essencialmente reformula a declaração de Sofia Lyall, representante da organização Statewatch — crítica do programa —, apresentada no último período do quarto parágrafo do texto.\*/ ||E|| - Incorreta. Apenas os itens II e III estão certos. O item I está errado. Consoante o primeiro parágrafo do texto, o programa encontra-se em fase de desenvolvimento, não estando ainda em uso. Adicionalmente, todo o restante do texto descreve as funcionalidades que o programa deverá apresentar no futuro, assim como os possíveis resultados — positivos e negativos — que poderão ser observados quando de sua efetiva implementação. O item II está certo. Consoante o segundo parágrafo do texto, de acordo com o Ministério da Justiça, defensor do programa, o projeto (o programa) forneceria subsídios ou elementos para aprimorar a avaliação de risco de crimes graves. O item III está certo. A afirmativa essencialmente reformula a declaração de Sofia Lyall, representante da organização Statewatch — crítica do programa —, apresentada no último período do quarto parágrafo do texto.\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,11,$q$Língua Inglesa$q$,$q$When text CG1A7 states that “The MoJ hopes the project will help boost public safety” (third paragraph), it means the Ministry of Justice is expressing A a fear. B a doubt. C a concern. D a suspicion. E an expectation.$q$,$q$When text CG1A7 states that “The MoJ hopes the project will help boost public safety” (third paragraph), it means the Ministry of Justice is expressing A a fear. B a doubt. C a concern. D a suspicion. E an expectation. || JUSTIFICATIVAS: ||A|| - Incorreta. No excerto em tela, o verbo que tem “MoJ” como sujeito é “hope”, que se traduz por “esperar”, no sentido de “ter esperança” ou “ter expectativa”. Trata-se, portanto, de um verbo que expressa uma expectativa positiva em relação a um evento futuro, ou seja, a ideia de que algo desejável venha a acontecer. Esse uso não denota medo (“fear”), dúvida (“doubt”), preocupação (“concern”) ou desconfiança (“suspicion”), mas, sim, uma projeção positiva quanto ao efeito esperado do projeto, qual seja, o aumento da segurança pública.\*/ ||B|| - Incorreta. No excerto em tela, o verbo que tem “MoJ” como sujeito é “hope”, que se traduz por “esperar”, no sentido de “ter esperança” ou “ter expectativa”. Trata-se, portanto, de um verbo que expressa uma expectativa positiva em relação a um evento futuro, ou seja, a ideia de que algo desejável venha a acontecer. Esse uso não denota medo (“fear”), dúvida (“doubt”), preocupação (“concern”) ou desconfiança (“suspicion”), mas, sim, uma projeção positiva quanto ao efeito esperado do projeto, qual seja, o aumento da segurança pública.\*/ ||C|| - Incorreta. No excerto em tela, o verbo que tem “MoJ” como sujeito é “hope”, que se traduz por “esperar”, no sentido de “ter esperança” ou “ter expectativa”. Trata-se, portanto, de um verbo que expressa uma expectativa positiva em relação a um evento futuro, ou seja, a ideia de que algo desejável venha a acontecer. Esse uso não denota medo (“fear”), dúvida (“doubt”), preocupação (“concern”) ou desconfiança (“suspicion”), mas, sim, uma projeção positiva quanto ao efeito esperado do projeto, qual seja, o aumento da segurança pública.\*/ ||D|| - Incorreta. No excerto em tela, o verbo que tem “MoJ” como sujeito é “hope”, que se traduz por “esperar”, no sentido de “ter esperança” ou “ter expectativa”. Trata-se, portanto, de um verbo que expressa uma expectativa positiva em relação a um evento futuro, ou seja, a ideia de que algo desejável venha a acontecer. Esse uso não denota medo (“fear”), dúvida (“doubt”), preocupação (“concern”) ou desconfiança (“suspicion”), mas, sim, uma projeção positiva quanto ao efeito esperado do projeto, qual seja, o aumento da segurança pública.\*/ ||E|| - Correta. No excerto em tela, o verbo que tem “MoJ” como sujeito é “hope”, que se traduz por “esperar”, no sentido de “ter esperança” ou “ter expectativa”. Trata-se, portanto, de um verbo que expressa uma expectativa positiva em relação a um evento futuro, ou seja, a ideia de que algo desejável venha a acontecer. Esse uso não denota medo (“fear”), dúvida (“doubt”), preocupação (“concern”) ou desconfiança (“suspicion”), mas, sim, uma projeção positiva quanto ao efeito esperado do projeto, qual seja, o aumento da segurança pública.\*/$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,12,$q$Língua Inglesa$q$,$q$Choose the option that presents the two verbs that best express the meaning of ‘profile’, in ‘Building an automated tool to profile people as violent criminals’ (last paragraph of text CG1A7). A detect and judge B monitor and arrest C accuse and sentence D identify and categorize E consider and prosecute$q$,$q$Choose the option that presents the two verbs that best express the meaning of ‘profile’, in ‘Building an automated tool to profile people as violent criminals’ (last paragraph of text CG1A7). A detect and judge B monitor and arrest C accuse and sentence D identify and categorize E consider and prosecute || JUSTIFICATIVAS: ||A|| - Incorreta. No excerto em tela, o verbo “profile” é empregado com o sentido de analisar e classificar pessoas com base em determinados dados ou características, a fim de associá-las a um determinado grupo, que, no caso em questão, envolveria pessoas consideradas propensas à prática de crimes violentos. Nesse contexto, “profile” não implica ação penal, prisão ou julgamento, mas sim um processo de identificação e categorização baseada em padrões predefinidos (comportamentais, históricos, estatísticos etc.). Assim, as opções “a” (que pode ser traduzida por detectar e julgar), “b” (monitorar e prender) e “c” (acusar e sentenciar) extrapolam o sentido de “profile”, pois envolvem etapas eventualmente posteriores ou externas ao ato de perfilar. Já a alternativa “e” (considerar e processar) simplesmente não define a ação expressa por “profile”.\*/ ||B|| - Incorreta. No excerto em tela, o verbo “profile” é empregado com o sentido de analisar e classificar pessoas com base em determinados dados ou características, a fim de associá-las a um determinado grupo, que, no caso em questão, envolveria pessoas consideradas propensas à prática de crimes violentos. Nesse contexto, “profile” não implica ação penal, prisão ou julgamento, mas sim um processo de identificação e categorização baseada em padrões predefinidos (comportamentais, históricos, estatísticos etc.). Assim, as opções “a” (que pode ser traduzida por detectar e julgar), “b” (monitorar e prender) e “c” (acusar e sentenciar) extrapolam o sentido de “profile”, pois envolvem etapas eventualmente posteriores ou externas ao ato de perfilar. Já a alternativa “e” (considerar e processar) simplesmente não define a ação expressa por “profile”.\*/ ||C|| - Incorreta. No excerto em tela, o verbo “profile” é empregado com o sentido de analisar e classificar pessoas com base em determinados dados ou características, a fim de associá-las a um determinado grupo, que, no caso em questão, envolveria pessoas consideradas propensas à prática de crimes violentos. Nesse contexto, “profile” não implica ação penal, prisão ou julgamento, mas sim um processo de identificação e categorização baseada em padrões predefinidos (comportamentais, históricos, estatísticos etc.). Assim, as opções “a” (que pode ser traduzida por detectar e julgar), “b” (monitorar e prender) e “c” (acusar e sentenciar) extrapolam o sentido de “profile”, pois envolvem etapas eventualmente posteriores ou externas ao ato de perfilar. Já a alternativa “e” (considerar e processar) simplesmente não define a ação expressa por “profile”.\*/ ||D|| - Correta. No excerto em tela, o verbo “profile” é empregado com o sentido de analisar e classificar pessoas com base em determinados dados ou características, a fim de associá-las a um determinado grupo, que, no caso em questão, envolveria pessoas consideradas propensas à prática de crimes violentos. Nesse contexto, “profile” não implica ação penal, prisão ou julgamento, mas sim um processo de identificação e categorização baseada em padrões predefinidos (comportamentais, históricos, estatísticos etc.). Assim, as opções “a” (que pode ser traduzida por detectar e julgar), “b” (monitorar e prender) e “c” (acusar e sentenciar) extrapolam o sentido de “profile”, pois envolvem etapas eventualmente posteriores ou externas ao ato de perfilar. Já a alternativa “e” (considerar e processar) simplesmente não define a ação expressa por “profile”.\*/ ||E|| - Incorreta. No excerto em tela, o verbo “profile” é empregado com o sentido de analisar e classificar pessoas com base em determinados dados ou características, a fim de associá-las a um determinado grupo, que, no caso em questão, envolveria pessoas consideradas propensas à prática de crimes violentos. Nesse contexto, “profile” não implica ação penal, prisão ou julgamento, mas sim um processo de identificação e categorização baseada em padrões predefinidos (comportamentais, históricos, estatísticos etc.). Assim, as opções “a” (que pode ser traduzida por detectar e julgar), “b” (monitorar e prender) e “c” (acusar e sentenciar) extrapolam o sentido de “profile”, pois envolvem etapas eventualmente posteriores ou externas ao ato de perfilar. Já a alternativa “e” (considerar e processar) simplesmente não define a ação expressa por “profile”.\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,13,$q$Legislação da PMDF$q$,$q$Com base na Lei n.º 7.289/1984, que dispõe sobre o Estatuto dos Policiais Militares da PMDF, julgue os itens a seguir. I O compromisso de honra do aspirante a oficial PM é prestado na solenidade de declaração de aspirante a oficial, conforme o cerimonial previsto no regulamento do estabelecimento de ensino. II A gravidade da violação dos preceitos da ética policial-militar independe do grau hierárquico de quem a cometer. III A subordinação não afeta, de modo algum, a dignidade pessoal do policial militar e decorre, exclusivamente, da estrutura hierarquizada da polícia militar. IV Aos policiais militares do DF é proibido realizar manifestações coletivas de caráter reivindicatório ou político, bem como relativas a atos de superiores. Estão certos apenas os itens A I e II. B I e III. C II e IV. D I, III e IV. E II, III e IV.$q$,$q$Com base na Lei n.º 7.289/1984, que dispõe sobre o Estatuto dos Policiais Militares da PMDF, julgue os itens a seguir. I O compromisso de honra do aspirante a oficial PM é prestado na solenidade de declaração de aspirante a oficial, conforme o cerimonial previsto no regulamento do estabelecimento de ensino. II A gravidade da violação dos preceitos da ética policial-militar independe do grau hierárquico de quem a cometer. III A subordinação não afeta, de modo algum, a dignidade pessoal do policial militar e decorre, exclusivamente, da estrutura hierarquizada da polícia militar. IV Aos policiais militares do DF é proibido realizar manifestações coletivas de caráter reivindicatório ou político, bem como relativas a atos de superiores. Estão certos apenas os itens A I e II. B I e III. C II e IV. D I, III e IV. E II, III e IV. || JUSTIFICATIVAS: ||A|| - Incorreta. O item II está errado. A violação dos preceitos da ética policial-militar é tão mais grave quanto mais elevado for o grau hierárquico de quem a cometer (Lei n.º 7.289/1984, art. 42, § 1.º).\*/ ||B|| - Incorreta. O item IV também está certo. São proibidas quaisquer manifestações coletivas, tanto sobre atos de superiores quanto as de caráter reivindicatório ou político (Lei nº 7.289/1984, art. 45).\*/ ||C|| - Incorreta. O item II está errado. A violação dos preceitos da ética policial-militar é tão mais grave quanto mais elevado for o grau hierárquico de quem a cometer (Lei nº 7.289/1984, art. 42, §1º).\*/ ||D|| - Correta. O item I está certo. O compromisso do aspirante a oficial PM é prestado na solenidade de declaração de aspirante a oficial, de acordo com o cerimonial previsto no regulamento do estabelecimento de ensino (Lei n.º 7.289/1984, art. 34, § 1.º). O item II está errado. A violação dos preceitos da ética policial- militar é tão mais grave quanto mais elevado for o grau hierárquico de quem a cometer (Lei n.º 7.289/1984, art. 42, § 1.º). O item III está certo. A subordinação não afeta, de modo algum, a dignidade pessoal do policial militar e decorre, exclusivamente, da estrutura hierarquizada da polícia militar (Lei n.º 7.289/1984, art. 36). O item IV está certo. São proibidas quaisquer manifestações coletivas, tanto sobre atos de superiores quanto as de caráter reivindicatório ou político (Lei n.º 7.289/1984, art. 45).\*/ ||E|| - Incorreta. O item II está errado. A violação dos preceitos da ética policial-militar é tão mais grave quanto mais elevado for o grau hierárquico de quem a cometer (Lei nº 7.289/1984, art. 42, §1º).\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,14,$q$Legislação da PMDF$q$,$q$À luz da Lei n.º 12.086/2009, assinale a opção correta. A No âmbito da PMDF, as promoções ocorrem pelos seguintes critérios: antiguidade, merecimento, ato de bravura e post mortem. B As atividades desenvolvidas pelos integrantes dos quadros da PMDF serão especificadas em ato do comandante-geral. C A distribuição do pessoal ativo da PMDF no quadro de organização da corporação, respeitados os quantitativos legalmente estabelecidos, será feita em ato do governador do DF. D O aspirante a oficial será promovido ao posto de segundo- tenente após o cumprimento dos requisitos na graduação, na primeira data de promoção, desde que haja vaga. E A progressão funcional do policial militar do DF continua após sua transferência para a inatividade, desde que sejam observados os interstícios de cada grau hierárquico e cumpridas as demais exigências estabelecidas para a promoção.$q$,$q$À luz da Lei n.º 12.086/2009, assinale a opção correta. A No âmbito da PMDF, as promoções ocorrem pelos seguintes critérios: antiguidade, merecimento, ato de bravura e post mortem. B As atividades desenvolvidas pelos integrantes dos quadros da PMDF serão especificadas em ato do comandante-geral. C A distribuição do pessoal ativo da PMDF no quadro de organização da corporação, respeitados os quantitativos legalmente estabelecidos, será feita em ato do governador do DF. D O aspirante a oficial será promovido ao posto de segundo- tenente após o cumprimento dos requisitos na graduação, na primeira data de promoção, desde que haja vaga. E A progressão funcional do policial militar do DF continua após sua transferência para a inatividade, desde que sejam observados os interstícios de cada grau hierárquico e cumpridas as demais exigências estabelecidas para a promoção. || JUSTIFICATIVAS: ||A|| - Correta. No âmbito da PMDF, as promoções ocorrem pelos seguintes critérios: antiguidade, merecimento, ato de bravura e post mortem (Lei n.º 12.086/2009, art. 6.º). \*/ ||B|| - Incorreta. As atividades desenvolvidas pelos integrantes dos quadros da PMDF serão especificadas em ato do governador do DF (Lei n.º 12.086/2009, art. 4.º).\*/ ||C|| - Incorreta. A distribuição do pessoal ativo PMDF no quadro de organização da corporação, respeitados os quantitativos estabelecidos nesta Lei, será feita em ato do comandante-geral (Lei n.º 12.086/2009, art. 3.º).\*/ ||D|| - Incorreta. O aspirante a oficial será promovido ao posto de segundo-tenente após o cumprimento dos requisitos na graduação, na primeira data de promoção, independentemente da existência de vagas (Lei n.º 12.086/2009, art. 35, parágrafo único).\*/ ||E|| - Incorreta. A progressão funcional do policial militar do Distrito Federal cessa com a sua transferência para a inatividade (Lei n.º 12.086/2009, art. 51).\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,15,$q$Legislação da PMDF$q$,$q$Segundo o Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), aprovado pelo Decreto n.º 88.777/1983, considera-se agregação a A situação em que se encontra o policial militar a serviço de órgão ou autoridade a que não esteja diretamente subordinado. B situação na qual o policial militar da ativa deixa de ocupar vaga na escala hierárquica de seu quadro, nela permanecendo sem número. C ordenação da autoridade, em níveis diferentes, dentro da estrutura das Forças Armadas e das forças auxiliares. D capacidade de uma organização policial-militar cumprir as missões a que se destina. E primazia para efeito de continência e sinais de respeito.$q$,$q$Segundo o Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), aprovado pelo Decreto n.º 88.777/1983, considera-se agregação a A situação em que se encontra o policial militar a serviço de órgão ou autoridade a que não esteja diretamente subordinado. B situação na qual o policial militar da ativa deixa de ocupar vaga na escala hierárquica de seu quadro, nela permanecendo sem número. C ordenação da autoridade, em níveis diferentes, dentro da estrutura das Forças Armadas e das forças auxiliares. D capacidade de uma organização policial-militar cumprir as missões a que se destina. E primazia para efeito de continência e sinais de respeito. || JUSTIFICATIVAS: ||A|| - Incorreta. Denomina-se “à disposição” a situação em que se encontra o policial militar a serviço de órgão ou autoridade a que não esteja diretamente subordinado (Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), art. 2.º, item 1).\*/ ||B|| - Correta. Agregação é a situação na qual o policial militar da ativa deixa de ocupar vaga na escala hierárquica do seu quadro, nela permanecendo sem número (Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), art. 2.º, item 3).\*/ ||C|| - Incorreta. Hierarquia militar é a ordenação da autoridade, em níveis diferentes, dentro da estrutura das Forças Armadas e Forças Auxiliares (Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), art. 2.º, item 15).\*/ ||D|| - Incorreta. Operacionalidade é a capacidade de uma organização policial-militar para cumprir as missões a que se destina (Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), art. 2.º, item 22).\*/ ||E|| - Incorreta. Precedência é a primazia para efeito de continência e sinais de respeito (Regulamento para as Polícias Militares e Corpos de Bombeiros Militares (R-200), art. 2.º, item 30).\*/$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,16,$q$Legislação da PMDF$q$,$q$No que diz respeito à organização básica da PMDF, julgue os itens a seguir, de acordo com o Decreto n.º 10.443/2020. I Compete ao Comando-Geral o planejamento das atividades, com vistas à organização da PMDF, ao atendimento das necessidades de pessoal e material e ao emprego para o cumprimento das missões. II O Alto-Comando é um órgão colegiado consultivo e de assessoramento permanente ao comandante-geral da PMDF. III O Estado-Maior é órgão de assessoramento do comandante-geral da PMDF e é responsável pelo planejamento estratégico da corporação. IV A Academia de Polícia Militar de Brasília está subordinada ao Departamento de Educação e Cultura da PMDF. Assinale a opção correta. A Apenas os itens I e IV estão certos. B Apenas os itens II e III estão certos. C Apenas os itens I, II e III estão certos. D Apenas os itens I, III e IV estão certos. E Todos os itens estão certos.$q$,$q$No que diz respeito à organização básica da PMDF, julgue os itens a seguir, de acordo com o Decreto n.º 10.443/2020. I Compete ao Comando-Geral o planejamento das atividades, com vistas à organização da PMDF, ao atendimento das necessidades de pessoal e material e ao emprego para o cumprimento das missões. II O Alto-Comando é um órgão colegiado consultivo e de assessoramento permanente ao comandante-geral da PMDF. III O Estado-Maior é órgão de assessoramento do comandante-geral da PMDF e é responsável pelo planejamento estratégico da corporação. IV A Academia de Polícia Militar de Brasília está subordinada ao Departamento de Educação e Cultura da PMDF. Assinale a opção correta. A Apenas os itens I e IV estão certos. B Apenas os itens II e III estão certos. C Apenas os itens I, II e III estão certos. D Apenas os itens I, III e IV estão certos. E Todos os itens estão certos. || JUSTIFICATIVAS: ||A|| - Incorreta. Os itens II e III também estão certos, conforme o Decreto n.º 10.443/2020, arts. 9.º e 11.\*/ ||B|| - Incorreta. Os itens I e IV também estão certos, conforme o Decreto n.º 10.443/2020, art. 4.º, II, e art. 17, III, a.\*/ ||C|| - Incorreta. O item IV também está certo, conforme o Decreto n.º 10.443/2020, art. 17, III, a.\*/ ||D|| - Incorreta. O item II também está certo, conforme o Decreto n.º 10.443/2020, art. 9.º.\*/ ||E|| - Correta. O item I está certo. Ao Comando-Geral compete o planejamento das atividades, com vistas à organização da PMDF, às necessidades de pessoal e material e ao emprego para o cumprimento das missões (Decreto n.º 10.443/2020, art. 4.º, II). O item II está certo. O Comandante-Geral da PMDF será assistido pelo Alto-Comando, órgão colegiado consultivo e de assessoramento permanente (Decreto n.º 10.443/2020, art. 9.º). O item III está certo. O Estado-Maior é órgão de assessoramento do Comandante-Geral da PMDF, responsável pelo planejamento estratégico e centro do sistema de planejamento, programação e orçamento (Decreto n.º 10.443/2020, art. 11). O item IV está certo. A Academia de Polícia Militar de Brasília está subordinada ao Departamento de Educação e Cultura (Decreto n.º 10.443/2020, art. 17, III, a).\*/$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,17,$q$Legislação da PMDF$q$,$q$De acordo com a Lei Orgânica do Distrito Federal, os objetivos da política de segurança pública I incluem a prevenção das infrações penais mediante policiamento ostensivo e procedimentos investigatórios. II não incluem a apuração das infrações penais por intermédio de procedimentos investigatórios de polícia judiciária. III não incluem o exercício da atividade de defesa civil, prevenção e combate a incêndios, alagamentos, enchentes e outros desastres. IV incluem a guarda dos prédios públicos do DF. Assinale a opção correta. A Apenas o item II está certo. B Apenas os itens I e IV estão certos. C Apenas os itens III e IV estão certos. D Apenas os itens I, II e III estão certos. E Todos os itens estão certos.$q$,$q$De acordo com a Lei Orgânica do Distrito Federal, os objetivos da política de segurança pública I incluem a prevenção das infrações penais mediante policiamento ostensivo e procedimentos investigatórios. II não incluem a apuração das infrações penais por intermédio de procedimentos investigatórios de polícia judiciária. III não incluem o exercício da atividade de defesa civil, prevenção e combate a incêndios, alagamentos, enchentes e outros desastres. IV incluem a guarda dos prédios públicos do DF. Assinale a opção correta. A Apenas o item II está certo. B Apenas os itens I e IV estão certos. C Apenas os itens III e IV estão certos. D Apenas os itens I, II e III estão certos. E Todos os itens estão certos. || JUSTIFICATIVAS: ||A|| - Incorreta. O item II é errado porque corresponde, sim, a objetivo da política de segurança pública conforme a LODF (art. 117-A, § 1.º, inciso II).\*/ ||B|| - Correta. Todos os itens descrevem objetivos da política de segurança pública, nos termos dos incisos do § 1.º do art. 117-A da LODF. Os itens II e III estão errados por negá-los.\*/ ||C|| - Incorreta. O item III é errado porque corresponde, sim, a objetivo da política de segurança pública conforme a LODF (art. 117-A, § 1.º, inciso III).\*/ ||D|| - Incorreta. Os itens II e III são errados porque correspondem, sim, a objetivos da política de segurança pública conforme a LODF (art. 117-A, § 1.º, incisos II e III).\*/ ||E|| - Incorreta. Os itens II e III são errados porque correspondem, sim, a objetivos da política de segurança pública conforme a LODF (art. 117-A, § 1.º, incisos II e III).\*/$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,18,$q$Legislação da PMDF$q$,$q$Com base nas disposições da Lei n.º 14.751/2023, que institui a Lei Orgânica Nacional das Polícias Militares dos Estados, do Distrito Federal e dos Territórios, assinale a opção correta. A O efetivo da PMDF é fixado em lei distrital, considerando-se a extensão da área territorial, a população, os índices de criminalidade, o índice de desenvolvimento humano e as condições socioeconômicas do DF, entre outros, conforme as peculiaridades locais. B Na estrutura básica hierárquica das polícias militares, generais e cadetes são considerados oficiais superiores e oficiais subalternos, respectivamente. C Em regra, os militares do DF têm a prerrogativa inerente ao exercício do cargo de serem presos somente por ordem escrita da autoridade judiciária competente ou em flagrante delito. D O comandante-geral da PMDF será nomeado por ato do presidente da República entre os oficiais da ativa do último posto do Quadro de Oficiais de Estado-Maior (QOEM). E Compete às polícias militares executar, prioritariamente, ressalvadas as competências da União e dos municípios, as ações de busca, salvamento e resgate e, privativamente, as ações de prevenção, combate e perícia administrativa de incêndios e de polícia judiciária militar.$q$,$q$Com base nas disposições da Lei n.º 14.751/2023, que institui a Lei Orgânica Nacional das Polícias Militares dos Estados, do Distrito Federal e dos Territórios, assinale a opção correta. A O efetivo da PMDF é fixado em lei distrital, considerando-se a extensão da área territorial, a população, os índices de criminalidade, o índice de desenvolvimento humano e as condições socioeconômicas do DF, entre outros, conforme as peculiaridades locais. B Na estrutura básica hierárquica das polícias militares, generais e cadetes são considerados oficiais superiores e oficiais subalternos, respectivamente. C Em regra, os militares do DF têm a prerrogativa inerente ao exercício do cargo de serem presos somente por ordem escrita da autoridade judiciária competente ou em flagrante delito. D O comandante-geral da PMDF será nomeado por ato do presidente da República entre os oficiais da ativa do último posto do Quadro de Oficiais de Estado-Maior (QOEM). E Compete às polícias militares executar, prioritariamente, ressalvadas as competências da União e dos municípios, as ações de busca, salvamento e resgate e, privativamente, as ações de prevenção, combate e perícia administrativa de incêndios e de polícia judiciária militar. || JUSTIFICATIVAS: ||A|| - Incorreta. Os efetivos da polícia militar e do corpo de bombeiro militar do DF e dos territórios, integrados pelos membros militares das instituições, nos termos do art. 42 da Constituição Federal de 1988, são fixados em lei federal, considerados a extensão da área territorial, a população, os índices de criminalidade, os riscos potenciais de desastres, o índice de desenvolvimento humano e as condições socioeconômicas da unidade federada ou dos territórios, entre outros, conforme as peculiaridades locais (Lei n.º 14.751/2023, art. 11).\*/ ||B|| - Incorreta. Na estrutura básica hierárquica das polícias militares, coronel, tenente-coronel e major são considerados oficiais superiores. Frisa-se que não há generais. Ademais, cadetes são considerados praças especiais (Lei n.º 14.751/2023, art. 12).\*/ ||C|| - Correta. Salvo as prisões disciplinares militares, os militares dos estados, do DF e dos territórios têm a prerrogativa inerente ao exercício do cargo de serem presos somente por ordem escrita da autoridade judiciária competente ou em flagrante delito, caso em que a autoridade respectiva fará imediata comunicação ao chefe do órgão de direção superior da respectiva instituição militar (Lei n.º 14.751/2023, art. 18, parágrafo único). \*/ ||D|| - Incorreta. Os comandantes-gerais das polícias militares e dos corpos de bombeiros militares dos estados, do DF e dos territórios serão nomeados por ato do governador entre os oficiais da ativa do último posto do Quadro de Oficiais de Estado-Maior e serão responsáveis, no âmbito da administração direta, perante os governadores das respectivas unidades federativas e territórios, pela administração e emprego da instituição (Lei n.º 14.751/2023, art. 29). \*/ ||E|| - Incorreta. Compete aos corpos de bombeiros militares dos estados, do DF e dos territórios, nos termos de suas atribuições constitucionais e legais, entre outras, executar, prioritariamente, ressalvada as competências da União e dos municípios, as ações de busca, salvamento e resgate e, privativamente, as ações de prevenção, combate e perícia administrativa de incêndios e de polícia judiciária militar (Lei n.º 14.751/2023, art. 6.º, II).\*/$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,19,$q$Realidade do Distrito Federal$q$,$q$No que se refere à Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE), julgue os itens a seguir. I A RIDE é composta exclusivamente pelo DF e por municípios do estado de Goiás. II São considerados de interesse da RIDE os serviços públicos comuns ao DF e aos municípios que a integram, ressalvados aqueles relacionados às áreas de infraestrutura e de geração de empregos. III Município eventualmente criado a partir do desmembramento de território de município que compõe a RIDE passará a compor, automaticamente, a referida região integrada. Assinale a opção correta. A Nenhum item está certo. B Apenas o item I está certo. C Apenas o item II está certo. D Apenas o item III está certo. E Todos os itens estão certos.$q$,$q$No que se refere à Região Integrada de Desenvolvimento do Distrito Federal e Entorno (RIDE), julgue os itens a seguir. I A RIDE é composta exclusivamente pelo DF e por municípios do estado de Goiás. II São considerados de interesse da RIDE os serviços públicos comuns ao DF e aos municípios que a integram, ressalvados aqueles relacionados às áreas de infraestrutura e de geração de empregos. III Município eventualmente criado a partir do desmembramento de território de município que compõe a RIDE passará a compor, automaticamente, a referida região integrada. Assinale a opção correta. A Nenhum item está certo. B Apenas o item I está certo. C Apenas o item II está certo. D Apenas o item III está certo. E Todos os itens estão certos. || JUSTIFICATIVAS: ||A|| - Incorreta. O item III está certo, pois os municípios que vierem a ser constituídos a partir de desmembramento de território de município que integra a RIDE, conforme art. 1.º, § 1.º, da LC n.º 94/1998, passarão a compor, automaticamente, a Região Integrada de Desenvolvimento do Distrito Federal e Entorno (Lei Complementar n.º 94/1998, art. 1.º, § 2.º).\*/ ||B|| - Incorreta. O item I está errado, pois a RIDE é composta pelo DF, por municípios de Goiás e por municípios de Minas Gerais (Lei Complementar n.º 94/1998, art. 1.º, § 1.º).\*/ ||C|| - Incorreta. O item II está errado, pois são considerados de interesse da RIDE os serviços públicos comuns ao DF e aos municípios que a integram, especialmente aqueles relacionados às áreas de infraestrutura e de geração de empregos (Lei Complementar n.º 94/1998, art. 3.º).\*/ ||D|| - Correta. O item I está errado, pois a RIDE é composta pelo DF, por municípios de Goiás e por municípios de Minas Gerais (Lei Complementar n.º 94/1998, art. 1.º, § 1.º). O item II está errado, pois são considerados de interesse da RIDE os serviços públicos comuns ao DF e aos municípios que a integram, especialmente aqueles relacionados às áreas de infraestrutura e de geração de empregos (Lei Complementar n.º 94/1998, art. 3.º). O item III está certo, pois os municípios que vierem a ser constituídos a partir de desmembramento de território de município que integra a RIDE, conforme art. 1.º, § 1.º, da LC n.º 94/1998, passarão a compor, automaticamente, a Região Integrada de Desenvolvimento do Distrito Federal e Entorno (Lei Complementar n.º 94/1998, art. 1.º, § 2.º).\*/ ||E|| - Incorreta. Os itens I e II estão errados, nos termos da Lei Complementar n.º 94/1998, art. 1.º, § 1.º, e art. 3.º.\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,20,$q$Realidade do Distrito Federal$q$,$q$No que diz respeito à realidade histórico-geográfica e política do DF, assinale a opção correta. A O DF elege somente quatro deputados federais e três senadores para o Congresso Nacional. B O DF divide-se em municípios, que também são chamados de regiões administrativas. C As competências legislativas do DF são idênticas somente às reservadas aos estados. D O Plano Piloto da cidade de Brasília foi selecionado por meio de um concurso vencido pelo arquiteto Oscar Niemeyer. E Em 1990, de forma inédita, os eleitores do DF escolheram pelo voto direto o seu governador e os primeiros deputados distritais.$q$,$q$No que diz respeito à realidade histórico-geográfica e política do DF, assinale a opção correta. A O DF elege somente quatro deputados federais e três senadores para o Congresso Nacional. B O DF divide-se em municípios, que também são chamados de regiões administrativas. C As competências legislativas do DF são idênticas somente às reservadas aos estados. D O Plano Piloto da cidade de Brasília foi selecionado por meio de um concurso vencido pelo arquiteto Oscar Niemeyer. E Em 1990, de forma inédita, os eleitores do DF escolheram pelo voto direto o seu governador e os primeiros deputados distritais. || JUSTIFICATIVAS: ||A|| - Incorreta. De acordo com a Constituição Federal de 1988, art. 45, § 1.º, e art. 46, § 1.º, o DF elege oito deputados federais e três senadores para o Congresso Nacional.\*/ ||B|| - Incorreta. De acordo com a Constituição Federal de 1988, art. 32, é vedada a divisão do DF em municípios. \*/ ||C|| - Incorreta. De acordo com a Constituição Federal de 1988, art. 32, § 1.º, ao DF são atribuídas as competências legislativas reservadas aos estados e municípios.\*/ ||D|| - Incorreta. O Plano Piloto da cidade de Brasília foi selecionado por meio de um concurso vencido pelo arquiteto e urbanista Lúcio Costa. Com o projeto urbanístico aprovado, o arquiteto Oscar Niemeyer foi escolhido como o responsável pela construção dos monumentos.\*/ ||E|| - Correta. Em 1990, de forma inédita, os eleitores do DF escolheram pelo voto direto o seu governador e os primeiros vinte e quatro deputados distritais. Em 1.º de janeiro de 1991, a Câmara Legislativa foi instalada no DF. Após 30 anos de espera pela autonomia política do DF, os 24 deputados distritais, eleitos pelo voto popular pela primeira vez, tomaram posse.\*/$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,21,$q$Realidade do Distrito Federal$q$,$q$Julgue os seguintes itens, relativos à realidade social, histórica, geográfica e cultural do DF. I Segundo dados do Instituto Brasileiro de Geografia e Estatística (IBGE), entre as 27 unidades federativas, o DF é a que possui a menor área territorial e a menor população. II O DF está integralmente inserido no bioma Cerrado. III O patrimônio cultural do DF é composto por bens materiais e imateriais. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$Julgue os seguintes itens, relativos à realidade social, histórica, geográfica e cultural do DF. I Segundo dados do Instituto Brasileiro de Geografia e Estatística (IBGE), entre as 27 unidades federativas, o DF é a que possui a menor área territorial e a menor população. II O DF está integralmente inserido no bioma Cerrado. III O patrimônio cultural do DF é composto por bens materiais e imateriais. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos. || JUSTIFICATIVAS: ||A|| - Incorreta. O item I está errado. De fato, o DF é a unidade federativa que possui menor área territorial. Entretanto, segundo os dados mais atuais do IBGE, Roraima é a unidade federativa menos populosa do país.\*/ ||B|| - Incorreta. O item também III está certo. O patrimônio cultural do Distrito Federal é composto por bens materiais (monumentos, edifícios ou sítios em razão de seus valores histórico, estético, arqueológico, científico, etnológico ou antropológico) e bens imateriais (saberes, celebrações, formas de expressão e lugares vinculados às práticas simbólicas, ritualísticas, artísticas, étnicas ou produtivas).\*/ ||C|| - Incorreta. O item I está errado. De fato, o DF é a unidade federativa que possui menor área territorial. Entretanto, segundo os dados mais atuais do IBGE, Roraima é a unidade federativa menos populosa do país.\*/ ||D|| - Correta. O item I está errado. De fato, o DF é a unidade federativa que possui menor área territorial. Entretanto, segundo os dados mais atuais do IBGE, Roraima é a unidade federativa menos populosa do país. O item II está certo. O DF está totalmente inserido no bioma cerrado. O item III está certo. O patrimônio cultural do DF é composto por bens materiais (monumentos, edifícios ou sítios em razão de seus valores histórico, estético, arqueológico, científico, etnológico ou antropológico) e bens imateriais (saberes, celebrações, formas de expressão e lugares vinculados às práticas simbólicas, ritualísticas, artísticas, étnicas ou produtivas).\*/ ||E|| - Incorreta. O item I está errado. De fato, o DF é a unidade federativa que possui menor área territorial. Entretanto, segundo os dados mais atuais do IBGE, Roraima é a unidade federativa menos populosa do país.\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,22,$q$Realidade do Distrito Federal$q$,$q$De acordo com o II Plano Distrital de Políticas para as Mulheres (II-PDPM), julgue os seguintes itens. I O II-PDPM consiste em um conjunto de propostas de políticas públicas elaboradas privativamente por órgãos governamentais para garantir a igualdade das mulheres e combater a discriminação de gênero. II As ações e metas previstas pelo II-PDPM estão distribuídas em três eixos temáticos. III Reduzir a taxa de desemprego de mulheres no DF e contribuir para a igualdade salarial entre homens e mulheres são, respectivamente, uma meta e um objetivo do mesmo eixo temático do II-PDPM. Assinale a opção correta. A Apenas o item II está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens I e III estão certos. E Todos os itens estão certos.$q$,$q$De acordo com o II Plano Distrital de Políticas para as Mulheres (II-PDPM), julgue os seguintes itens. I O II-PDPM consiste em um conjunto de propostas de políticas públicas elaboradas privativamente por órgãos governamentais para garantir a igualdade das mulheres e combater a discriminação de gênero. II As ações e metas previstas pelo II-PDPM estão distribuídas em três eixos temáticos. III Reduzir a taxa de desemprego de mulheres no DF e contribuir para a igualdade salarial entre homens e mulheres são, respectivamente, uma meta e um objetivo do mesmo eixo temático do II-PDPM. Assinale a opção correta. A Apenas o item II está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens I e III estão certos. E Todos os itens estão certos. || JUSTIFICATIVAS: ||A|| - Incorreta. O item II está errado. O II-PDPM contempla ações e metas distribuídas em nove eixos temáticos.\*/ ||B|| - Correta. O item I está errado. O II-PDPM consiste em conjunto de propostas de políticas públicas elaboradas por órgãos governamentais, não governamentais e sociedade civil para garantir a igualdade das mulheres e combater a discriminação de gênero. O item II está errado. O II-PDPM contempla ações e metas distribuídas em nove eixos temáticos. O item III está certo. Reduzir a taxa de desemprego de mulheres no DF e contribuir para a igualdade salarial entre homens e mulheres são, respectivamente, meta e objetivo específico do Eixo 1 – Igualdade no Mundo do Trabalho e Autonomia Econômica.\*/ ||C|| - Incorreta. O item I está errado. O II-PDPM consiste em conjunto de propostas de políticas públicas elaboradas por órgãos governamentais, não governamentais e sociedade civil para garantir a igualdade das mulheres e combater a discriminação de gênero. O item II está errado. O II-PDPM contempla ações e metas distribuídas em nove eixos temáticos.\*/ ||D|| - Incorreta. O item I está errado. O II-PDPM consiste em conjunto de propostas de políticas públicas elaboradas por órgãos governamentais, não governamentais e sociedade civil para garantir a igualdade das mulheres e combater a discriminação de gênero.\*/ ||E|| - Incorreta. Apenas o item III está certo.\*/$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,23,$q$Realidade do Distrito Federal$q$,$q$Ainda no que concerne ao II-PDPM, assinale a opção correta. A No âmbito do II-PDPM, o único eixo que considera expressamente aspectos como raça, etnia, orientação sexual e identidade de gênero das mulheres é o eixo relativo ao enfrentamento de racismo, sexismo, lesbofobia e transfobia. B Ampliar o acesso e o número de vagas para matrículas de mulheres e seus filhos desde a educação básica até a formação profissionalizante e superior é uma meta inserida no eixo relativo à igualdade no mundo do trabalho e autonomia econômica. C No II-PDPM, reduzir a incidência de gravidez na adolescência e aumentar o número de mulheres assistidas pela saúde prisional são metas previstas no eixo relativo ao enfrentamento de todas as formas de violência contra as mulheres. D Aumentar o número de mulheres em cargos de decisão no âmbito do governo do DF e promover a participação das mulheres no planejamento urbano das cidades são, respectivamente, um objetivo específico e uma meta do II-PDPM. E A promoção da igualdade de direitos e de oportunidades para mulheres jovens, mulheres idosas e mulheres com deficiência é objetivo geral de um dos eixos do II-PDPM.$q$,$q$Ainda no que concerne ao II-PDPM, assinale a opção correta. A No âmbito do II-PDPM, o único eixo que considera expressamente aspectos como raça, etnia, orientação sexual e identidade de gênero das mulheres é o eixo relativo ao enfrentamento de racismo, sexismo, lesbofobia e transfobia. B Ampliar o acesso e o número de vagas para matrículas de mulheres e seus filhos desde a educação básica até a formação profissionalizante e superior é uma meta inserida no eixo relativo à igualdade no mundo do trabalho e autonomia econômica. C No II-PDPM, reduzir a incidência de gravidez na adolescência e aumentar o número de mulheres assistidas pela saúde prisional são metas previstas no eixo relativo ao enfrentamento de todas as formas de violência contra as mulheres. D Aumentar o número de mulheres em cargos de decisão no âmbito do governo do DF e promover a participação das mulheres no planejamento urbano das cidades são, respectivamente, um objetivo específico e uma meta do II-PDPM. E A promoção da igualdade de direitos e de oportunidades para mulheres jovens, mulheres idosas e mulheres com deficiência é objetivo geral de um dos eixos do II-PDPM. || JUSTIFICATIVAS: ||A|| - Incorreta. Esses aspectos interseccionais são considerados em vários outros eixos, sendo, inclusive, expressamente mencionados. Por exemplo, no eixo relativo à saúde reprodutiva e direitos sexuais (Eixo 3), um dos objetivos específicos é “Promover os direitos sexuais e os direitos reprodutivos de todas as mulheres, com a implantação de iniciativas afirmativas e inovadoras, considerando-se as suas características geracionais, de raça, etnia, orientação sexual, identidade de gênero, local de moradia, trabalho, deficiência e situação de privação de liberdade”. \*/ ||B|| - Incorreta. Trata-se de meta associada ao Eixo 2 – Educação para a Igualdade. O eixo a que a opção se refere é o Eixo 1 – Igualdade no Mundo do Trabalho e Autonomia Econômica. \*/ ||C|| - Incorreta. Trata-se de metas previstas no Eixo 3 – Saúde Integral das Mulheres, Direitos Sexuais e Reprodutivos. \*/ ||D|| - Incorreta. Aumentar o número de mulheres em cargos de decisão no âmbito do governo do DF e promover a participação das mulheres no planejamento urbano das cidades são, respectivamente, meta e objetivo específico do Eixo 5 – Participação das Mulheres nos Espaços de Poder e Decisão.\*/ ||E|| - Correta. A promoção da igualdade de direitos e de oportunidades para mulheres jovens, mulheres idosas e mulheres com deficiência é objetivo geral do Eixo 9 – Igualdade para as Mulheres Jovens, Mulheres Idosas e Mulheres com Deficiência. \*/$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,24,$q$Realidade do Distrito Federal$q$,$q$Conforme estabelecido no II-PDPM, uma das metas do Eixo 4, que diz respeito ao enfrentamento de todas as formas de violência contra as mulheres, é A aumentar o número de serviços de abrigamento (casas abrigo, abrigamento provisório). B reduzir a taxa de desemprego de mulheres no DF. C ampliar o número de escolas contempladas com ações do programa Maria da Penha Vai à Escola. D aumentar o número de mulheres assistidas pela saúde prisional. E implantar a agenda das mulheres rurais no DF.$q$,$q$Conforme estabelecido no II-PDPM, uma das metas do Eixo 4, que diz respeito ao enfrentamento de todas as formas de violência contra as mulheres, é A aumentar o número de serviços de abrigamento (casas abrigo, abrigamento provisório). B reduzir a taxa de desemprego de mulheres no DF. C ampliar o número de escolas contempladas com ações do programa Maria da Penha Vai à Escola. D aumentar o número de mulheres assistidas pela saúde prisional. E implantar a agenda das mulheres rurais no DF. || JUSTIFICATIVAS: ||A|| - Correta. Aumentar o número de serviços de abrigamento (casas abrigo, abrigamento provisório) é uma das metas do Eixo 4 – Enfrentamento de Todas as Formas de Violência contra as Mulheres.\*/ ||B|| - Incorreta. Reduzir a taxa de desemprego de mulheres no DF é uma das metas do Eixo 1 – Igualdade no Mundo do Trabalho e Autonomia Econômica.\*/ ||C|| - Incorreta. Ampliar o número de escolas contempladas com ações do programa “Maria da Penha Vai à Escola” é uma das metas do Eixo 2 – Educação para Igualdade.\*/ ||D|| - Incorreta. Aumentar o número de mulheres assistidas pela saúde prisional é uma das metas do Eixo 3 – Saúde Integral das Mulheres, Direitos Sexuais e Reprodutivos.\*/ ||E|| - Incorreta. Implantar a agenda das mulheres rurais no DF é uma das metas do Eixo 6 – Igualdade para as Mulheres Rurais.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,25,$q$Direitos Humanos$q$,$q$Assinale a opção correta no que se refere aos direitos humanos, de acordo com as disposições da Constituição Federal de 1988 (CF) e o entendimento do STF. A A prevalência dos direitos humanos faz parte dos princípios que regem as relações internacionais brasileiras. B Os tratados e convenções sobre direitos humanos serão incorporados ao ordenamento jurídico brasileiro, sem a necessidade de expedição do decreto de promulgação. C Os tratados e convenções sobre direitos humanos são automaticamente equiparados às emendas constitucionais, visto que são direitos fundamentais e independem de qualquer rito especial de equiparação. D A dignidade da pessoa humana inclui-se entre os objetivos fundamentais da República Federativa do Brasil. E Somente as normas garantidoras dos direitos individuais têm aplicação imediata.$q$,$q$Assinale a opção correta no que se refere aos direitos humanos, de acordo com as disposições da Constituição Federal de 1988 (CF) e o entendimento do STF. A A prevalência dos direitos humanos faz parte dos princípios que regem as relações internacionais brasileiras. B Os tratados e convenções sobre direitos humanos serão incorporados ao ordenamento jurídico brasileiro, sem a necessidade de expedição do decreto de promulgação. C Os tratados e convenções sobre direitos humanos são automaticamente equiparados às emendas constitucionais, visto que são direitos fundamentais e independem de qualquer rito especial de equiparação. D A dignidade da pessoa humana inclui-se entre os objetivos fundamentais da República Federativa do Brasil. E Somente as normas garantidoras dos direitos individuais têm aplicação imediata. || JUSTIFICATIVAS: ||A|| - Correta, de acordo com a previsão do artigo 4.º, inciso II, da Constituição Federal de 1988, a seguir transcrito. Art. 4.º A República Federativa do Brasil rege-se nas suas relações internacionais pelos seguintes princípios: (...) II – prevalência dos direitos humanos; (...).\*/ ||B|| - Incorreta. A formação da vontade do Brasil em celebrar tratado internacional deve obedecer às quatro fases de formação (assinatura, decreto legislativo, ratificação e decreto de promulgação). Segundo entendimento do STF, há necessidade de promulgação na ordem interna para que o tratado seja considerado válido, o que é realizado por meio de decreto do presidente da República.\*/ ||C|| - Incorreta. De acordo com os §§ 2.º e 3.º do art. 5.º da Constituição Federal de 1988, há necessidade de incorporação dos tratados sobre direitos humanos via ritos específicos. Art. 5.º (...) § 2.º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte. § 3.º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais.\*/ ||D|| - Incorreta. De acordo com o artigo 1.º da Constituição Federal de 1988, a dignidade da pessoa humana constitui um fundamento da República Federativa do Brasil, e não um objetivo. Art. 1.º A República Federativa do Brasil, formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal, constitui-se em Estado Democrático de Direito e tem como fundamentos: III - a dignidade da pessoa humana;\*/ ||E|| - Incorreta. Segundo a Constituição Federal de 1988 (art. 5.º, § 1.º), “As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata”, dispositivo que representa um avanço em matéria de direitos humanos, pois abrange os direitos fundamentais.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,26,$q$Direitos Humanos$q$,$q$Como parte da Política Nacional dos Direitos Humanos, o Programa Nacional de Direitos Humanos (PNDH-3) prevê a modernização do marco normativo do sistema de segurança pública mediante ações programáticas que incluem A revisar a estrutura dos órgãos de segurança pública para garantir que seus órgãos corregedores se subordinem à direção das instituições policiais. B facultar a criação de ouvidorias de polícias independentes nos estados e no DF, com ouvidores protegidos por mandato e escolhidos pelo secretário de segurança local. C definir o ciclo completo da atividade policial, com competências comuns a todas as polícias, independentemente da natureza e da gravidade dos delitos. D propor alteração do texto constitucional para considerar as polícias militares não mais como forças auxiliares do Exército, mas apenas como força reserva. E instituir seguro para quaisquer casos de acidentes ou morte em serviço para os profissionais do sistema de segurança pública.$q$,$q$Como parte da Política Nacional dos Direitos Humanos, o Programa Nacional de Direitos Humanos (PNDH-3) prevê a modernização do marco normativo do sistema de segurança pública mediante ações programáticas que incluem A revisar a estrutura dos órgãos de segurança pública para garantir que seus órgãos corregedores se subordinem à direção das instituições policiais. B facultar a criação de ouvidorias de polícias independentes nos estados e no DF, com ouvidores protegidos por mandato e escolhidos pelo secretário de segurança local. C definir o ciclo completo da atividade policial, com competências comuns a todas as polícias, independentemente da natureza e da gravidade dos delitos. D propor alteração do texto constitucional para considerar as polícias militares não mais como forças auxiliares do Exército, mas apenas como força reserva. E instituir seguro para quaisquer casos de acidentes ou morte em serviço para os profissionais do sistema de segurança pública. || JUSTIFICATIVAS: ||A|| - Incorreta. PNDH-3, Eixo Orientador IV, Diretriz 11, objetivo estratégico I: modernização do marco normativo do sistema de segurança pública, ações programáticas: “b) Propor a revisão da estrutura, treinamento, controle, emprego e regimentos disciplinares dos órgãos de segurança pública, de forma a potencializar as suas funções de combate ao crime e proteção dos direitos de cidadania, bem como garantir que seus órgãos corregedores disponham de carreira própria, sem subordinação à direção das instituições policiais.” (p. 106).\*/ ||B|| - Incorreta. PNDH-3, Eixo Orientador IV, Diretriz 11, objetivo estratégico I: modernização do marco normativo do sistema de segurança pública, ações programáticas: “c) Propor a criação obrigatória de ouvidorias de polícias independentes nos estados e no Distrito Federal, com ouvidores protegidos por mandato e escolhidos com participação da sociedade” (p. 107).\*/ ||C|| - Incorreta. PNDH-3, Eixo Orientador IV, Diretriz 11, objetivo estratégico I: modernização do marco normativo do sistema de segurança pública, ações programáticas: “e) Promover o aprofundamento do debate sobre a instituição do ciclo completo da atividade policial, com competências repartidas pelas polícias, a partir da natureza e da gravidade dos delitos.” (p. 107).\*/ ||D|| - Correta. PNDH-3, Eixo Orientador IV, Diretriz 11, objetivo estratégico I: modernização do marco normativo do sistema de segurança pública, ações programáticas: “a) Propor alteração do texto constitucional, de modo a considerar as polícias militares não mais como forças auxiliares do Exército, mantendo-as apenas como força reserva. Responsável: Ministério da Justiça. Parceiro: Secretaria de Relações Institucionais da Presidência da República” (p. 106).\*/ ||E|| - Incorreta. PNDH-3, Eixo Orientador IV, Diretriz 11, objetivo estratégico III: promoção dos direitos humanos dos profissionais do sistema de segurança pública, assegurando sua formação continuada e compatível com as atividades que exercem; ações programáticas: “d) Propor projeto de lei instituindo seguro para casos de acidentes incapacitantes ou morte em serviço para os profissionais do sistema de segurança pública” (p. 109).\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,27,$q$Segurança Pública$q$,$q$Determinado estado da Federação instituiu política voltada à segurança pública, com foco na ampliação do encarceramento e no aumento da repressão policial, em detrimento da capacidade de inteligência, de medidas alternativas e de políticas de prevenção. Nessa situação hipotética, a política pública de segurança instituída é A compatível com o Programa Nacional de Direitos Humanos (PNDH-3), que prioriza a repressão penal como estratégia central de combate à violência. B parcialmente compatível com o Programa Nacional de Direitos Humanos (PNDH-3), pois apenas a ampliação do sistema prisional é uma diretriz prioritária do PNDH-3. C incompatível com o Programa Nacional de Direitos Humanos (PNDH-3), que prioriza a prevenção da violência e medidas alternativas à privação de liberdade. D compatível com o Programa Nacional de Direitos Humanos (PNDH-3), desde que garantida a participação social efetiva no sistema prisional. E incompatível com o Programa Nacional de Direitos Humanos (PNDH-3) apenas se comprovada a ocorrência de violações de direitos humanos dentro do sistema prisional do estado.$q$,$q$Determinado estado da Federação instituiu política voltada à segurança pública, com foco na ampliação do encarceramento e no aumento da repressão policial, em detrimento da capacidade de inteligência, de medidas alternativas e de políticas de prevenção. Nessa situação hipotética, a política pública de segurança instituída é A compatível com o Programa Nacional de Direitos Humanos (PNDH-3), que prioriza a repressão penal como estratégia central de combate à violência. B parcialmente compatível com o Programa Nacional de Direitos Humanos (PNDH-3), pois apenas a ampliação do sistema prisional é uma diretriz prioritária do PNDH-3. C incompatível com o Programa Nacional de Direitos Humanos (PNDH-3), que prioriza a prevenção da violência e medidas alternativas à privação de liberdade. D compatível com o Programa Nacional de Direitos Humanos (PNDH-3), desde que garantida a participação social efetiva no sistema prisional. E incompatível com o Programa Nacional de Direitos Humanos (PNDH-3) apenas se comprovada a ocorrência de violações de direitos humanos dentro do sistema prisional do estado. || JUSTIFICATIVAS: ||A|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. O Eixo IV do PNDH-3 (Decreto n.º 7.037/2009), que trata de Segurança Pública, Acesso à Justiça e Combate à Violência, não prioriza repressão penal como eixo central. Ao contrário, ele promove o combate à violência enfatizando a prevenção e as medidas alternativas.\*/ ||B|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. O Eixo IV do PNDH-3, que trata de Segurança Pública, Acesso à Justiça e Combate à Violência, não apresenta como diretriz prioritária a ampliação do sistema prisional. Ao contrário, o programa propõe a redução da centralidade da prisão.\*/ ||C|| - Correta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. O Eixo IV do PNDH-3, que trata de Segurança Pública, Acesso à Justiça e Combate à Violência, prevê como diretrizes as medidas alternativas à privação de liberdade, a prevenção da violência e a reforma do sistema penal com foco em direitos humanos.\*/ ||D|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. O Eixo IV do PNDH-3, que trata de Segurança Pública, Acesso à Justiça e Combate à Violência, prevê como diretriz a participação social, mas somente esse fato não legitima uma política pública de segurança centrada no encarceramento. \*/ ||E|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. O Eixo IV do PNDH-3, que trata de Segurança Pública, Acesso à Justiça e Combate à Violência, indica que a incompatibilidade não depende somente de violações internas dentro do sistema prisional; ela se concretiza na própria lógica punitivista presente na política pública de segurança instituída, contrária à Política Nacional de Direitos Humanos.\*/$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,28,$q$Segurança Pública$q$,$q$Acerca da responsabilidade pelas ações programáticas de fortalecimento dos instrumentos de prevenção à violência conforme o PNDH-3, assinale a opção correta. A A realização anual de pesquisas nacionais de vitimização e o estímulo à discussão de modelos alternativos de tratamento do uso de drogas competem exclusivamente ao Ministério da Justiça. B A elaboração de diretrizes para atuação conjunta dos órgãos de trânsito com os de segurança pública para reduzir a violência no trânsito é responsabilidade compartilhada entre o Ministério da Justiça e o Ministério das Cidades. C O fortalecimento de mecanismos que possibilitem a efetiva fiscalização de empresas de segurança privada é atribuição do Gabinete de Segurança Institucional em conjunto com a Secretaria Especial dos Direitos Humanos. D A elaboração de diretrizes de prevenção à violência com recorte de gênero e raça é competência privativa da Secretaria Especial de Políticas de Promoção da Igualdade Racial da Presidência da República. E A normatização e a fiscalização dos serviços de segurança privada que atuam na área rural são responsabilidade do Ministério da Justiça em conjunto com o Ministério da Saúde.$q$,$q$Acerca da responsabilidade pelas ações programáticas de fortalecimento dos instrumentos de prevenção à violência conforme o PNDH-3, assinale a opção correta. A A realização anual de pesquisas nacionais de vitimização e o estímulo à discussão de modelos alternativos de tratamento do uso de drogas competem exclusivamente ao Ministério da Justiça. B A elaboração de diretrizes para atuação conjunta dos órgãos de trânsito com os de segurança pública para reduzir a violência no trânsito é responsabilidade compartilhada entre o Ministério da Justiça e o Ministério das Cidades. C O fortalecimento de mecanismos que possibilitem a efetiva fiscalização de empresas de segurança privada é atribuição do Gabinete de Segurança Institucional em conjunto com a Secretaria Especial dos Direitos Humanos. D A elaboração de diretrizes de prevenção à violência com recorte de gênero e raça é competência privativa da Secretaria Especial de Políticas de Promoção da Igualdade Racial da Presidência da República. E A normatização e a fiscalização dos serviços de segurança privada que atuam na área rural são responsabilidade do Ministério da Justiça em conjunto com o Ministério da Saúde. || JUSTIFICATIVAS: ||A|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. A realização anual de pesquisas nacionais de vitimização é responsabilidade do Ministério da Justiça e da Secretaria Especial dos Direitos Humanos da Presidência da República. O estímulo à discussão sobre modelos alternativos de tratamento do uso e tráfico de drogas, considerando o paradigma da redução de danos, é responsabilidade do Ministério da Justiça, da Secretaria Especial dos Direitos Humanos da Presidência da República, do Gabinete de Segurança Institucional e do Ministério da Saúde. (Eixo Orientador IV: Segurança Pública, Acesso à Justiça e Combate à Violência. Diretriz 13: Prevenção da violência e da criminalidade e profissionalização da investigação de atos criminosos. Objetivo estratégico IV: “b” e “g”).\*/ ||B|| - Correta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. Eixo Orientador IV: Segurança Pública, Acesso à Justiça e Combate à Violência. Diretriz 13: Prevenção da violência e da criminalidade e profissionalização da investigação de atos criminosos. Objetivo estratégico IV: “f”.\*/ ||C|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. O fortalecimento de mecanismos que possibilitem a efetiva fiscalização de empresas de segurança privada é responsabilidade do Ministério da Justiça e da Secretaria Especial dos Direitos Humanos da Presidência da República. (Eixo Orientador IV: Segurança Pública, Acesso à Justiça e Combate à Violência. Diretriz 13: Prevenção da violência e da criminalidade e profissionalização da investigação de atos criminosos. Objetivo estratégico IV: “c”).\*/ ||D|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. A elaboração de diretrizes de prevenção à violência com recorte de gênero e raça compete ao Ministério da Justiça, à Secretaria Especial de Políticas para as Mulheres da Presidência da República e à Secretaria Especial de Políticas de Promoção da Igualdade Racial da Presidência da República (Eixo Orientador IV: Segurança Pública, Acesso à Justiça e Combate à Violência. Diretriz 13: Prevenção da violência e da criminalidade e profissionalização da investigação de atos criminosos. Objetivo estratégico IV: “a”).\*/ ||E|| - Incorreta. 5 Política Nacional de Direitos Humanos; políticas de segurança pública voltadas para grupos vulneráveis. O desenvolvimento de normas de conduta e fiscalização dos serviços de segurança privados que atuam na área rural é responsabilidade somente do Ministério da Justiça (Eixo Orientador IV: Segurança Pública, Acesso à Justiça e Combate à Violência. Diretriz 13: Prevenção da violência e da criminalidade e profissionalização da investigação de atos criminosos. Objetivo estratégico IV: “d”).\*/$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,29,$q$Segurança Pública$q$,$q$À luz da afirmação histórica dos direitos humanos, considerando o Bill of Rights (1698) e a Declaração Universal dos Direitos Humanos (1948), é correto afirmar que A ambos os documentos consolidam a ideia de igualdade essencial entre todos os seres humanos. B a principal diferença entre esses documentos reside na sua forma jurídica, pois, a rigor, sua estrutura é igual. C a Declaração Universal dos Direitos Humanos mantém a lógica do Bill of Rights ao restringir direitos a determinados grupos sociais. D ambos os documentos apresentam o mesmo fundamento filosófico e alcance normativo. E o Bill of Rights se funda na limitação do poder político em determinado contexto, enquanto a Declaração Universal dos Direitos Humanos afirma direitos inerentes à condição humana.$q$,$q$À luz da afirmação histórica dos direitos humanos, considerando o Bill of Rights (1698) e a Declaração Universal dos Direitos Humanos (1948), é correto afirmar que A ambos os documentos consolidam a ideia de igualdade essencial entre todos os seres humanos. B a principal diferença entre esses documentos reside na sua forma jurídica, pois, a rigor, sua estrutura é igual. C a Declaração Universal dos Direitos Humanos mantém a lógica do Bill of Rights ao restringir direitos a determinados grupos sociais. D ambos os documentos apresentam o mesmo fundamento filosófico e alcance normativo. E o Bill of Rights se funda na limitação do poder político em determinado contexto, enquanto a Declaração Universal dos Direitos Humanos afirma direitos inerentes à condição humana. || JUSTIFICATIVAS: ||A|| - Incorreta. 2 Afirmação histórica dos direitos humanos 7 Declaração Universal dos Direitos Humanos. A igualdade essencial entre todos os seres humanos se consolida somente com a DUDH.\*/ ||B|| - Incorreta. 2 Afirmação histórica dos direitos humanos 7 Declaração Universal dos Direitos Humanos. A diferença entre os documentos é material, de conteúdo e estrutural, além de formal e jurídica.\*/ ||C|| - Incorreta. 2 Afirmação histórica dos direitos humanos 7 Declaração Universal dos Direitos Humanos. A DUDH rompe com a lógica do Bill Of Rights na medida em que declara expressamente a igualdade essencial de todo ser humano em sua dignidade de pessoa, ao passo que, anteriormente, o objetivo era acabar com o regime de monarquia absoluta, o que beneficiaria somente a parte da população ainda privilegiada.\*/ ||D|| - Incorreta. 2 Afirmação histórica dos direitos humanos 7 Declaração Universal dos Direitos Humanos. Há uma mudança profunda entre um documento e o outro, o que não permite afirmar que possuem o mesmo fundamento filosófico e igual alcance normativo, especialmente porque a DUDH é o resultado de uma evolução profunda no sentido de igualdade, liberdade e fraternidade, indo de uma discussão pontual e histórica do Bill Of Rights até a universalização dos direitos e garantias da DUDH.\*/ ||E|| - Correta. 2 Afirmação histórica dos direitos humanos 7 Declaração Universal dos Direitos Humanos. A DUDH representa a culminância de um processo ético que, iniciado com a Declaração de Independência dos Estados Unidos e a Declaração dos Direitos do Homem e do Cidadão, da Revolução Francesa, levou ao reconhecimento da igualdade essencial de todo ser humano em sua dignidade de pessoa; por sua vez, o Bill of Rights pôs fim, pela primeira vez, desde o seu surgimento na Europa renascentista, ao regime de monarquia absoluta, no qual todo poder emana do rei e em seu nome é exercido. Assim, a DUDH afirma direitos inerentes à condição humana, enquanto o Bill of Rights se funda na limitação do poder político na época do absolutismo inglês.\*/$q$,'X',1,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (PM-DF 2025, CFO, cargo Oficial Policial Militar - 2º Tenente); não é exibido aos estudantes.$q$),
(2025,30,$q$Segurança Pública$q$,$q$Todos os direitos humanos reconhecidos gozam da mesma proteção jurídica, não sendo cabível a proteção de uns em detrimento de outros. Essa ideia sintetiza o atributo dos direitos humanos denominado A indivisibilidade. B relatividade. C efetividade. D transnacionalidade. E inalienabilidade.$q$,$q$Todos os direitos humanos reconhecidos gozam da mesma proteção jurídica, não sendo cabível a proteção de uns em detrimento de outros. Essa ideia sintetiza o atributo dos direitos humanos denominado A indivisibilidade. B relatividade. C efetividade. D transnacionalidade. E inalienabilidade. || JUSTIFICATIVAS: ||A|| - Correta. 1 Teoria geral dos direitos humanos. 1.1 Conceitos, terminologia, estrutura normativa, fundamentação. A indivisibilidade está ligada ao objetivo maior do sistema internacional de direitos humanos, a promoção e garantia da dignidade humana. Não existe meio-termo: só há vida verdadeiramente digna se todos os direitos previstos no direito internacional dos direitos humanos estiverem sendo respeitados, sejam civis e políticos, sejam econômicos, sociais e culturais. Trata-se de uma característica do conjunto de normas e não de cada direito individualmente considerado.\*/ ||B|| - Incorreta. 1 Teoria geral dos direitos humanos. 1.1 Conceitos, terminologia, estrutura normativa, fundamentação. O atributo da relatividade diz respeito à possibilidade de os direitos humanos sofrerem limitações, não sendo, portanto, absolutos.\*/ ||C|| - Incorreta. 1 Teoria geral dos direitos humanos. 1.1 Conceitos, terminologia, estrutura normativa, fundamentação. A efetividade determina que não basta o singelo reconhecimento pelo Estado dos direitos humanos; ele deve empregar medidas efetivas para a sua aplicação.\*/ ||D|| - Incorreta. 1 Teoria geral dos direitos humanos. 1.1 Conceitos, terminologia, estrutura normativa, fundamentação. A transnacionalidade é a ideia de que os direitos fundamentais da pessoa humana são reconhecidos e protegidos por todos os Estados, embora existam variações quanto à enumeração desses direitos, bem como quanto à forma de protegê-los. Esses direitos não dependem da nacionalidade ou cidadania, sendo assegurados a qualquer pessoa.\*/ ||E|| - Incorreta. 1 Teoria geral dos direitos humanos. 1.1 Conceitos, terminologia, estrutura normativa, fundamentação. Os direitos humanos não podem ser alienados, transferidos, ainda que com anuência de seu titular, e qualquer manifestação de vontade nesse sentido é nula de pleno direito.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,31,$q$Criminologia$q$,$q$A criminologia A é uma ciência jurídica e autônoma que estabelece as punições adequadas para os crimes. B adota o método empírico para a apreciação do fato delituoso, de modo que sua análise parte da regra jurídica para o fato. C é uma ciência empírica e interdisciplinar que estuda o fenômeno criminal em sua complexidade. D estuda o delito e o comportamento desviante do delinquente, não comportando análise sobre a vítima do delito. E tem autonomia científica, por isso não se relaciona com as outras áreas do conhecimento.$q$,$q$A criminologia A é uma ciência jurídica e autônoma que estabelece as punições adequadas para os crimes. B adota o método empírico para a apreciação do fato delituoso, de modo que sua análise parte da regra jurídica para o fato. C é uma ciência empírica e interdisciplinar que estuda o fenômeno criminal em sua complexidade. D estuda o delito e o comportamento desviante do delinquente, não comportando análise sobre a vítima do delito. E tem autonomia científica, por isso não se relaciona com as outras áreas do conhecimento. || JUSTIFICATIVAS: ||A|| - Incorreta. A criminologia é uma ciência empírica, não uma ciência jurídica ou normativa (característica relacionada ao direito penal).\*/ ||B|| - Incorreta. A criminologia adota o empirismo e a interdisciplinaridade como métodos. Com o advento da fase científica da criminologia, passou-se a utilizar o método empírico ou experimental e indutivo, cunhado pela escola positiva, para estudar seu objeto, partindo-se da análise dos fatos, da realidade, da prática, do mundo do ser para a regra, com base no método biológico e sociológico. Já o direito, ciência cultural, contrariamente, vale-se do método dedutivo, partindo da regra jurídica para o fato.\*/ ||C|| - Correta. A criminologia é uma ciência empírica (baseada na observação da realidade) e interdisciplinar, integrando conceitos e conteúdo de outras áreas (psicologia, psiquiatria, sociologia, entre outras).\*/ ||D|| - Incorreta. A vítima e o controle social também integram os objetos de estudo da criminologia.\*/ ||E|| - Incorreta. A interdisciplinaridade é característica intrínseca da criminologia, sendo considerada um de seus métodos.\*/$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,32,$q$Criminologia$q$,$q$Assinale a opção correta no que se refere à criminologia e à política criminal. A A criminologia não possui função prática na formulação de políticas públicas, papel característico da política criminal. B A criminologia é uma ciência que fixa as penas a serem aplicadas pelo Poder Judiciário e orienta a política criminal na prevenção especial dos crimes. C A política criminal ignora os dados empíricos fornecidos pela criminologia, pois se baseia tão somente no direito penal. D A criminologia subsidia a política criminal, fornecendo dados científicos sobre o fenômeno da criminalidade. E A criminologia atua exclusivamente na repressão estatal de crimes mais graves, enquanto a política criminal atua na prevenção dos crimes socialmente relevantes.$q$,$q$Assinale a opção correta no que se refere à criminologia e à política criminal. A A criminologia não possui função prática na formulação de políticas públicas, papel característico da política criminal. B A criminologia é uma ciência que fixa as penas a serem aplicadas pelo Poder Judiciário e orienta a política criminal na prevenção especial dos crimes. C A política criminal ignora os dados empíricos fornecidos pela criminologia, pois se baseia tão somente no direito penal. D A criminologia subsidia a política criminal, fornecendo dados científicos sobre o fenômeno da criminalidade. E A criminologia atua exclusivamente na repressão estatal de crimes mais graves, enquanto a política criminal atua na prevenção dos crimes socialmente relevantes. || JUSTIFICATIVAS: ||A|| - Incorreta. A criminologia tem função prática, especialmente na formulação de políticas públicas.\*/ ||B|| - Incorreta. Não é função da criminologia cominar pena aos delitos, função esta incumbida ao direito penal.\*/ ||C|| - Incorreta. A política criminal contemporânea busca embasamento científico.\*/ ||D|| - Correta. A criminologia oferece informações empíricas e críticas que subsidiam políticas criminais mais eficazes e humanas.\*/ ||E|| - Incorreta. A criminologia atua na prevenção e análise de todos os tipos de delitos, não só dos mais graves.\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,33,$q$Criminologia$q$,$q$A criminologia ambiental tem como foco principal A a compreensão de como o ambiente físico pode influenciar a ocorrência de delitos e a prevenção situacional do crime. B a análise dos impactos das leis ambientais sobre o comportamento delituoso. C o estudo da relação existente entre desastres naturais e aumento da criminalidade. D a propositura de sanções administrativas mais eficazes contra os agentes de crimes ambientais. E o desenvolvimento de políticas penais mais rígidas para a proteção do meio ambiente.$q$,$q$A criminologia ambiental tem como foco principal A a compreensão de como o ambiente físico pode influenciar a ocorrência de delitos e a prevenção situacional do crime. B a análise dos impactos das leis ambientais sobre o comportamento delituoso. C o estudo da relação existente entre desastres naturais e aumento da criminalidade. D a propositura de sanções administrativas mais eficazes contra os agentes de crimes ambientais. E o desenvolvimento de políticas penais mais rígidas para a proteção do meio ambiente. || JUSTIFICATIVAS: ||A|| - Correta. A criminologia ambiental analisa como o ambiente físico (iluminação, visibilidade, barreiras, design urbano) influencia a ocorrência de crimes e como a arquitetura urbana pode prevenir delitos.\*/ ||B|| - Incorreta. A análise dos impactos das leis ambientais sobre o comportamento delituoso não é objeto da criminologia ambiental, mas do direito ambiental.\*/ ||C|| - Incorreta. O estudo da relação existente entre desastres naturais e aumento da criminalidade não consiste no foco primordial da criminologia ambiental.\*/ ||D|| - Incorreta. A propositura de sanções administrativas mais eficazes contra os agentes de crimes ambientais é atribuição afeta à gestão pública e ao direito administrativo.\*/ ||E|| - Incorreta. Políticas penais rígidas não são o foco da criminologia ambiental.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,34,$q$Criminologia$q$,$q$Acerca dos modelos de prevenção criminal no Estado democrático de direito, assinale a opção correta. A A prevenção secundária destina-se à população, visando ao controle social e formal e ao combate ao crime por meio da implementação de políticas públicas educacionais. B A prevenção terciária, implementada por meio de medidas punitivas e ressocializadoras, é voltada ao recluso e visa evitar a sua reincidência criminal por meio de medidas de reintegração social. C A prevenção primária atua diretamente sobre o apenado para modificar o seu comportamento, constituindo prevenção realizada de curto a médio prazo e com baixo custo. D A prevenção primária consiste na atuação repressiva das polícias ao fato criminoso mediante a implementação de mecanismos de neutralização do agente do crime. E A prevenção terciária visa à identificação de grupos criminosos antes da prática delitiva e à implementação efetiva de medidas que evitem o conflito.$q$,$q$Acerca dos modelos de prevenção criminal no Estado democrático de direito, assinale a opção correta. A A prevenção secundária destina-se à população, visando ao controle social e formal e ao combate ao crime por meio da implementação de políticas públicas educacionais. B A prevenção terciária, implementada por meio de medidas punitivas e ressocializadoras, é voltada ao recluso e visa evitar a sua reincidência criminal por meio de medidas de reintegração social. C A prevenção primária atua diretamente sobre o apenado para modificar o seu comportamento, constituindo prevenção realizada de curto a médio prazo e com baixo custo. D A prevenção primária consiste na atuação repressiva das polícias ao fato criminoso mediante a implementação de mecanismos de neutralização do agente do crime. E A prevenção terciária visa à identificação de grupos criminosos antes da prática delitiva e à implementação efetiva de medidas que evitem o conflito. || JUSTIFICATIVAS: ||A|| - Incorreta. A prevenção primária, e não a secundária, tem como destinatária a população e efetiva-se pelo controle social e formal e pela concretização de políticas sociais, econômicas e culturais.\*/ ||B|| - Correta. A prevenção terciária tem como foco evitar a reincidência. É implementada por meio das medidas de punição e ressocialização do processo de execução penal.\*/ ||C|| - Incorreta. A prevenção primária consiste na adoção de políticas públicas para a prevenção dos delitos e tem como destinatária toda a população, buscando enfrentar a origem da criminalidade.\*/ ||D|| - Incorreta. A prevenção secundária, e não a primária, é direcionada aos potenciais ou eventuais criminosos, realizando-se de curto a médio prazo, sendo um exemplo a prevenção policial.\*/ ||E|| - Incorreta. A prevenção secundária, e não a prevenção terciária, é direcionada aos potenciais ou eventuais criminosos.\*/$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,35,$q$Criminologia$q$,$q$O modelo de reação ao crime que confere à vítima o papel mais ativo no fenômeno criminal, propugnando procedimentos de mediação, conciliação e reparação do dano, é denominado A modelo dissuasório, que se baseia na racionalidade do criminoso para dissuadir a prática delitiva. B modelo ressocializador, cujo objetivo é a reinserção social do infrator por meio da solidariedade social. C modelo clássico, que coloca o Estado no centro da resposta ao fenômeno criminal junto à vítima. D modelo ressocializador, que reconhece os efeitos estigmatizantes da pena e privilegia a reparação do dano à vítima. E modelo integrador, que busca conciliar o conflito, reparar o dano e conferir protagonismo à vítima.$q$,$q$O modelo de reação ao crime que confere à vítima o papel mais ativo no fenômeno criminal, propugnando procedimentos de mediação, conciliação e reparação do dano, é denominado A modelo dissuasório, que se baseia na racionalidade do criminoso para dissuadir a prática delitiva. B modelo ressocializador, cujo objetivo é a reinserção social do infrator por meio da solidariedade social. C modelo clássico, que coloca o Estado no centro da resposta ao fenômeno criminal junto à vítima. D modelo ressocializador, que reconhece os efeitos estigmatizantes da pena e privilegia a reparação do dano à vítima. E modelo integrador, que busca conciliar o conflito, reparar o dano e conferir protagonismo à vítima. || JUSTIFICATIVAS: ||A|| - Incorreta. O modelo dissuasório não confere protagonismo à vítima, que, assim como a comunidade, ocupa posição marginal nesse modelo. A posição central é ocupada, sobretudo, pelo Estado e pelo delinquente.\*/ ||B|| - Incorreta. O modelo ressocializador centra-se na figura do infrator, não da vítima. Segundo esse modelo, o castigo existiria para o bem do delinquente. Nesse modelo, a dignidade do infrator é exaltada, sendo deixados de lado os interesses da vítima.\*/ ||C|| - Incorreta. O modelo clássico, também denominado dissuasório ou retributivo, não confere protagonismo à vítima. Ocupam a posição central desse modelo o Estado e o delinquente.\*/ ||D|| - Incorreta. Embora o reconhecimento dos efeitos estigmatizantes da pena seja, de fato, característica do modelo ressocializador, a reparação do dano à vítima não é seu objetivo. Nesse modelo, a dignidade do infrator é exaltada, sendo deixados de lado os interesses da vítima.\*/ ||E|| - Correta. O modelo integrador busca conciliar o conflito, reparar o dano e pacificar as relações sociais. Comparado aos modelos dissuasório e ressocializador, o modelo integrador é o que confere à vítima o papel mais ativo na resposta do delito e o que caracteriza mais apropriadamente o pensamento criminológico contemporâneo.\*/$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,36,$q$Criminologia$q$,$q$Assinale a opção que indica a teoria criminológica segundo a qual sinais visíveis de desordem e abandono em um ambiente incentivam comportamentos criminosos. A teoria das janelas quebradas B teoria da associação diferencial C teoria da anomia D teoria do etiquetamento social E teoria da escolha racional$q$,$q$Assinale a opção que indica a teoria criminológica segundo a qual sinais visíveis de desordem e abandono em um ambiente incentivam comportamentos criminosos. A teoria das janelas quebradas B teoria da associação diferencial C teoria da anomia D teoria do etiquetamento social E teoria da escolha racional || JUSTIFICATIVAS: ||A|| - Correta. A teoria das janelas quebradas surgiu nos EUA a partir dos estudos do cientista político James Wilson e do psicólogo criminologista Georg Kelling, com a publicação, em 1982, do trabalho intitulado Broken Windows. The Police and Neighborhood Safety na revista Atlantic Monthly, estabelecendo uma relação de causalidade entre a criminalidade e a desordem.\*/ ||B|| - Incorreta. A teoria da associação diferencial sustenta que o comportamento criminoso é aprendido por meio da interação social com pessoas que apresentam atitudes favoráveis à violação da lei. O foco está no processo de aprendizagem interpessoal, e não na influência do ambiente físico ou dos sinais de desordem urbana.\*/ ||C|| - Incorreta. A teoria da anomia explica o crime como resultado da tensão entre as metas culturalmente valorizadas pela sociedade e a falta de meios legítimos para alcançá-las. Trata-se de uma abordagem estrutural e social, sem relação com a desordem visual do ambiente.\*/ ||D|| - Incorreta. A teoria do etiquetamento social é uma abordagem que analisa como a rotulação de um indivíduo como criminoso pela sociedade e pelo sistema de justiça contribui para a consolidação de uma carreira desviante. O centro da análise é a reação social sobre o indivíduo, e não a influência do ambiente físico sobre o comportamento.\*/ ||E|| - Incorreta. A teoria da escolha racional parte do pressuposto de que o criminoso age de forma racional, avaliando custos e benefícios antes de praticar o delito. Não aponta relação entre a situação de visível abandono do ambiente e a conduta punível.\*/$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,37,$q$Raciocínio Lógico-Matemático$q$,$q$Considere que uma equipe com 9 policiais militares que trabalham 5 dias por semana atenda 645 ocorrências. Se o número total de policiais dessa equipe aumentar para 12 e eles continuarem trabalhando 5 dias por semana, mantida a mesma produtividade por policial, essa nova equipe atenderá A menos de 790 ocorrências. B entre 795 e 810 ocorrências. C entre 815 e 830 ocorrências. D entre 835 e 850 ocorrências. E mais de 855 ocorrências.$q$,$q$Considere que uma equipe com 9 policiais militares que trabalham 5 dias por semana atenda 645 ocorrências. Se o número total de policiais dessa equipe aumentar para 12 e eles continuarem trabalhando 5 dias por semana, mantida a mesma produtividade por policial, essa nova equipe atenderá A menos de 790 ocorrências. B entre 795 e 810 ocorrências. C entre 815 e 830 ocorrências. D entre 835 e 850 ocorrências. E mais de 855 ocorrências. || JUSTIFICATIVAS: ||A|| - Incorreta. Se a equipe com 9 policiais atende 645 ocorrências, a equipe com 12 policiais deverá atender um número de ocorrências que é proporcional a 645. Logo, o número de ocorrências por policial deverá ser mantido. Denotando-se por x a quantidade de ocorrências atendidas pela equipe com 12 policiais, 645/9 = x/12. Portanto, x = 12×645/9 = 860. O número de ocorrências atendidas pela equipe com 12 policiais que trabalha 5 dias por semana será igual a 860.\*/ ||B|| - Incorreta. Se a equipe com 9 policiais atende 645 ocorrências, a equipe com 12 policiais deverá atender um número de ocorrências que é proporcional a 645. Logo, o número de ocorrências por policial deverá ser mantido. Denotando-se por x a quantidade de ocorrências atendidas pela equipe com 12 policiais, 645/9 = x/12. Portanto, x = 12×645/9 = 860. O número de ocorrências atendidas pela equipe com 12 policiais que trabalha 5 dias por semana será igual a 860.\*/ ||C|| - Incorreta. Se a equipe com 9 policiais atende 645 ocorrências, a equipe com 12 policiais deverá atender um número de ocorrências que é proporcional a 645. Logo, o número de ocorrências por policial deverá ser mantido. Denotando-se por x a quantidade de ocorrências atendidas pela equipe com 12 policiais, 645/9 = x/12. Portanto, x = 12×645/9 = 860. O número de ocorrências atendidas pela equipe com 12 policiais que trabalha 5 dias por semana será igual a 860.\*/ ||D|| - Incorreta. Se a equipe com 9 policiais atende 645 ocorrências, a equipe com 12 policiais deverá atender um número de ocorrências que é proporcional a 645. Logo, o número de ocorrências por policial deverá ser mantido. Denotando-se por x a quantidade de ocorrências atendidas pela equipe com 12 policiais, 645/9 = x/12. Portanto, x = 12×645/9 = 860. O número de ocorrências atendidas pela equipe com 12 policiais que trabalha 5 dias por semana será igual a 860.\*/ ||E|| - Correta. Se a equipe com 9 policiais atende 645 ocorrências, a equipe com 12 policiais deverá atender um número de ocorrências que é proporcional a 645. Logo, o número de ocorrências por policial deverá ser mantido. Denotando-se por x a quantidade de ocorrências atendidas pela equipe com 12 policiais, 645/9 = x/12. Portanto, x = 12×645/9 = 860. O número de ocorrências atendidas pela equipe com 12 policiais que trabalha 5 dias por semana será igual a 860.\*/$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,38,$q$Raciocínio Lógico-Matemático$q$,$q$soldado cabo homem 180 120 mulher 120 80 A tabela precedente apresenta dados sobre o perfil de 500 policiais militares em início de carreira. Para cada um desses policiais, foi produzida uma ficha funcional, e todas essas fichas foram armazenadas em uma pasta. Na situação hipotética precedente, a probabilidade de se retirar da referida pasta, de maneira aleatória, uma ficha relativa a uma mulher com a patente de cabo é A igual ou superior a 0,31. B igual ou superior a 0,24 e inferior a 0,30. C igual ou superior a 0,18 e inferior a 0,23. D igual ou superior a 0,11 e inferior a 0,17. E inferior a 0,10.$q$,$q$soldado cabo homem 180 120 mulher 120 80 A tabela precedente apresenta dados sobre o perfil de 500 policiais militares em início de carreira. Para cada um desses policiais, foi produzida uma ficha funcional, e todas essas fichas foram armazenadas em uma pasta. Na situação hipotética precedente, a probabilidade de se retirar da referida pasta, de maneira aleatória, uma ficha relativa a uma mulher com a patente de cabo é A igual ou superior a 0,31. B igual ou superior a 0,24 e inferior a 0,30. C igual ou superior a 0,18 e inferior a 0,23. D igual ou superior a 0,11 e inferior a 0,17. E inferior a 0,10. || JUSTIFICATIVAS: ||A|| - Incorreta. A probabilidade de uma ficha retirada aleatoriamente ser de uma mulher é igual a 200/500 = 0,4. A probabilidade de uma ficha retirada aleatoriamente ser de um policial com patente cabo é igual a 200/500 = 0,4. Portanto, a probabilidade de uma ficha retirada aleatoriamente ser de uma mulher cuja patente é cabo é igual a 0,4 × 0,4 = 0,16.\*/ ||B|| - Incorreta. A probabilidade de uma ficha retirada aleatoriamente ser de uma mulher é igual a 200/500 = 0,4. A probabilidade de uma ficha retirada aleatoriamente ser de um policial com patente cabo é igual a 200/500 = 0,4. Portanto, a probabilidade de uma ficha retirada aleatoriamente ser de uma mulher cuja patente é cabo é igual a 0,4 × 0,4 = 0,16.\*/ ||C|| - Incorreta. A probabilidade de uma ficha retirada aleatoriamente ser de uma mulher é igual a 200/500 = 0,4. A probabilidade de uma ficha retirada aleatoriamente ser de um policial com patente cabo é igual a 200/500 = 0,4. Portanto, a probabilidade de uma ficha retirada aleatoriamente ser de uma mulher cuja patente é cabo é igual a 0,4 × 0,4 = 0,16.\*/ ||D|| - Correta. A probabilidade de uma ficha retirada aleatoriamente ser de uma mulher é igual a 200/500 = 0,4. A probabilidade de uma ficha retirada aleatoriamente ser de um policial com patente cabo é igual a 200/500 = 0,4. Portanto, a probabilidade de uma ficha retirada aleatoriamente ser de uma mulher cuja patente é cabo é igual a 0,4 × 0,4 = 0,16.\*/ ||E|| - Incorreta. A probabilidade de uma ficha retirada aleatoriamente ser de uma mulher é igual a 200/500 = 0,4. A probabilidade de uma ficha retirada aleatoriamente ser de um policial com patente cabo é igual a 200/500 = 0,4. Portanto, a probabilidade de uma ficha retirada aleatoriamente ser de uma mulher cuja patente é cabo é igual a 0,4 × 0,4 = 0,16.\*/$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,39,$q$Raciocínio Lógico-Matemático$q$,$q$Em um período de 20 horas, a quantidade de chamadas para o número de emergência da polícia militar realizadas a cada hora é descrita pela função Q(t) a seguir, em que 1 ≤ t ≤ 20. Q(t) = −t2 + 11t + 276 A partir dessas informações, assinale a opção que corresponde ao valor de t na situação em que Q(t) = 250. A 8 B 10 C 13 D 16 E 19$q$,$q$Em um período de 20 horas, a quantidade de chamadas para o número de emergência da polícia militar realizadas a cada hora é descrita pela função Q(t) a seguir, em que 1 ≤ t ≤ 20. Q(t) = −t2 + 11t + 276 A partir dessas informações, assinale a opção que corresponde ao valor de t na situação em que Q(t) = 250. A 8 B 10 C 13 D 16 E 19 || JUSTIFICATIVAS: ||A|| - Incorreta. −t2 + 11t + 276 = 250 implica na equação −t2 + 11t + 26, que tem duas raízes: t= −2 e t=13. Logo, t = 13 é a opção correta.\*/ ||B|| - Incorreta. −t2 + 11t + 276 = 250 implica na equação −t2 + 11t + 26, que tem duas raízes: t= −2 e t=13. Logo, t = 13é a opção correta.\*/ ||C|| - Correta. −t2 + 11t + 276 = 250 implica na equação −t2 + 11t + 26, que tem duas raízes: t= −2 e t=13. Logo, t = 13é a opção correta.\*/ ||D|| - Incorreta. −t2 + 11t + 276 = 250 implica na equação −t2 + 11t + 26, que tem duas raízes: t= −2 e t=13. Logo, t = 13é a opção correta.\*/ ||E|| - Incorreta. −t2 + 11t + 276 = 250 implica na equação −t2 + 11t + 26, que tem duas raízes: t= −2 e t=13. Logo, t = 13 é a opção correta.\*/$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,40,$q$Raciocínio Lógico-Matemático$q$,$q$Suponha que uma pesquisa realizada com um grupo de 350 policiais militares revele que, entre estes, 200 já estudaram em instituições de ensino públicas e 200 já estudaram em instituições de ensino particulares. Nessa situação, o número de policiais participantes da pesquisa que estudaram tanto em instituições de ensino públicas quanto em instituições de ensino particulares é A igual ou superior a 48 e inferior a 52. B igual ou superior a 53 e inferior a 57. C igual ou superior a 58 e inferior a 62. D igual ou superior a 63 e inferior a 67. E igual ou superior a 68 e inferior a 72.$q$,$q$Suponha que uma pesquisa realizada com um grupo de 350 policiais militares revele que, entre estes, 200 já estudaram em instituições de ensino públicas e 200 já estudaram em instituições de ensino particulares. Nessa situação, o número de policiais participantes da pesquisa que estudaram tanto em instituições de ensino públicas quanto em instituições de ensino particulares é A igual ou superior a 48 e inferior a 52. B igual ou superior a 53 e inferior a 57. C igual ou superior a 58 e inferior a 62. D igual ou superior a 63 e inferior a 67. E igual ou superior a 68 e inferior a 72. || JUSTIFICATIVAS: ||A|| - Correta. Denotando-se x como o número de policiais que estudaram apenas em instituições de ensino públicas, y como os que estudaram em instituições de ensino públicas e particulares e z como os que estudaram apenas em instituições de ensino particulares, o número total, ou seja, x + y + z, é igual a 350. Os que estudaram em instituições de ensino públicas, ou seja, x + y, equivale a 200, e os que estudaram em instituições de ensino particulares, ou seja, y + z, equivale a 200. Logo, x = 200 – y e z = 200 – y. Portanto, 200 – y + y + 200 – y = 350 400 – y = 350 y = 50.\*/ ||B|| - Incorreta. Denotando-se x como o número de policiais que estudaram apenas em instituições de ensino públicas, y como os que estudaram em instituições de ensino públicas e particulares e z como os que estudaram apenas em instituições de ensino particulares, o número total, ou seja, x + y + z, é igual a 350. Os que estudaram em instituições de ensino públicas, ou seja, x + y, equivale a 200, e os que estudaram em instituições de ensino particulares, ou seja, y + z, equivale a 200. Logo, x = 200 – y e z = 200 – y. Portanto, 200 – y + y + 200 – y = 350 400 – y = 350 y = 50.\*/ ||C|| - Incorreta. Denotando-se x como o número de policiais que estudaram apenas em instituições de ensino públicas, y como os que estudaram em instituições de ensino públicas e particulares e z como os que estudaram apenas em instituições de ensino particulares, o número total, ou seja, x + y + z, é igual a 350. Os que estudaram em instituições de ensino públicas, ou seja, x + y, equivale a 200, e os que estudaram em instituições de ensino particulares, ou seja, y + z, equivale a 200. Logo, x = 200 – y e z = 200 – y. Portanto, 200 – y + y + 200 – y = 350 400 – y = 350 y = 50.\*/ ||D|| - Incorreta. Denotando-se x como o número de policiais que estudaram apenas em instituições de ensino públicas, y como os que estudaram em instituições de ensino públicas e particulares e z como os que estudaram apenas em instituições de ensino particulares, o número total, ou seja, x + y + z, é igual a 350. Os que estudaram em instituições de ensino públicas, ou seja, x + y, equivale a 200, e os que estudaram em instituições de ensino particulares, ou seja, y + z, equivale a 200. Logo, x = 200 – y e z = 200 – y. Portanto, 200 – y + y + 200 – y = 350 400 – y = 350 y = 50.\*/ ||E|| - Incorreta. Denotando-se x como o número de policiais que estudaram apenas em instituições de ensino públicas, y como os que estudaram em instituições de ensino públicas e particulares e z como os que estudaram apenas em instituições de ensino particulares, o número total, ou seja, x + y + z, é igual a 350. Os que estudaram em instituições de ensino públicas, ou seja, x + y, equivale a 200, e os que estudaram em instituições de ensino particulares, ou seja, y + z, equivale a 200. Logo, x = 200 – y e z = 200 – y. Portanto, 200 – y + y + 200 – y = 350 400 – y = 350 y = 50.\*/ <https://www.planalto.gov.br/ccivil_03/Constituicao/Constituicao.htm#art42> <https://www.planalto.gov.br/ccivil_03/Constituicao/Constituicao.htm#art42>$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,41,$q$Administração Pública$q$,$q$No que se refere às funções da administração, assinale a opção correta. A Planejamento é a função administrativa destinada a lidar com os cenários presentes e analisar os cenários passados. B A função diretiva se exime de abordar questões relativas à liderança, focalizando aspectos concernentes à comunicação. C A função de organização prescinde da análise de estruturas hierárquicas. D Os parâmetros de desempenho estão relacionados à função de controle, tendo proeminente papel na obtenção dos resultados organizacionais. E A função de organização é equivalente à função de direção, pois ambas lidam com os aspectos imprevisíveis relacionados à consecução dos objetivos organizacionais.$q$,$q$No que se refere às funções da administração, assinale a opção correta. A Planejamento é a função administrativa destinada a lidar com os cenários presentes e analisar os cenários passados. B A função diretiva se exime de abordar questões relativas à liderança, focalizando aspectos concernentes à comunicação. C A função de organização prescinde da análise de estruturas hierárquicas. D Os parâmetros de desempenho estão relacionados à função de controle, tendo proeminente papel na obtenção dos resultados organizacionais. E A função de organização é equivalente à função de direção, pois ambas lidam com os aspectos imprevisíveis relacionados à consecução dos objetivos organizacionais. || JUSTIFICATIVAS: ||A|| - Incorreta. A função de planejamento concentra-se nos cenários futuros.\*/ ||B|| - Incorreta. Na direção, as questões de liderança são proeminentes, quando aplicáveis.\*/ ||C|| - Incorreta. A função de organização se baseia, entre outros aspectos, na análise de estruturas hierárquicas.\*/ ||D|| - Correta. A função de controle se debruça, principalmente, sobre a definição e o acompanhamento dos resultados organizacionais almejados.\*/ ||E|| - Incorreta. As duas funções lidam com a imprevisão contemporânea, no entanto de forma distinta e com enfoques diferentes, não sendo equivalentes. \*/$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,42,$q$Administração Pública$q$,$q$Em relação ao comportamento organizacional, assinale a opção correta. A O uso de tecnologias disruptivas pela organização exerce pouca ou nenhuma influência sobre o comportamento organizacional. B A influência da pesquisa de clima organizacional sobre o comportamento organizacional é irrelevante. C A dinâmica do comportamento organizacional é resultado de questões relacionadas a liderança, tecnologia e cultura, entre outros fatores intervenientes. D A estratégia consiste em padrão perene de comportamento organizacional. E A existência de comportamento organizacional flexível e de liderança servidora é fator de garantia inequívoca do êxito organizacional.$q$,$q$Em relação ao comportamento organizacional, assinale a opção correta. A O uso de tecnologias disruptivas pela organização exerce pouca ou nenhuma influência sobre o comportamento organizacional. B A influência da pesquisa de clima organizacional sobre o comportamento organizacional é irrelevante. C A dinâmica do comportamento organizacional é resultado de questões relacionadas a liderança, tecnologia e cultura, entre outros fatores intervenientes. D A estratégia consiste em padrão perene de comportamento organizacional. E A existência de comportamento organizacional flexível e de liderança servidora é fator de garantia inequívoca do êxito organizacional. || JUSTIFICATIVAS: \-- CONHECIMENTOS ESPECÍFICOS -- ||A|| - Incorreta. A implementação de tecnologias disruptivas exerce, em geral, impacto relevante sobre o comportamento organizacional. \*/ ||B|| - Incorreta. A pesquisa de clima organizacional pode evidenciar fatores relevantes e determinantes, até certo ponto, do comportamento organizacional.\*/ ||C|| - Correta. Tipo de liderança, tecnologias adotadas e cultura organizacional são aspectos que atuam sobre a dinâmica do comportamento organizacional.\*/ ||D|| - Incorreta. A estratégia constitui um padrão dinâmico, sem a característica de perenidade, em geral.\*/ ||E|| - Incorreta. Apesar de poder ser uma combinação poderosa, é inviável afirmar, inequivocamente, que a existência de um comportamento organizacional flexível e de uma liderança servidora é garantia de êxito organizacional.\*/$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,43,$q$Administração Pública$q$,$q$Assinale a opção correta a respeito do ciclo PDCA. A O aspecto cíclico do PDCA existe para garantir que a organização atinja sua excelência de forma disruptiva. B O teórico que concebeu o ciclo PDCA foi Ishikawa, que buscava uma nova abordagem para a gestão da qualidade. C A aplicação do PDCA é imprescindível no nível estratégico da organização, devendo, entretanto, ser evitada em outros níveis organizacionais. D A etapa de ação, contemplada no ciclo PDCA, diz respeito à execução primária do ato planejado, dispensando possíveis correções. E Devido a seu caráter incremental, o ciclo PDCA pode contribuir para a obtenção de melhoria organizacional contínua.$q$,$q$Assinale a opção correta a respeito do ciclo PDCA. A O aspecto cíclico do PDCA existe para garantir que a organização atinja sua excelência de forma disruptiva. B O teórico que concebeu o ciclo PDCA foi Ishikawa, que buscava uma nova abordagem para a gestão da qualidade. C A aplicação do PDCA é imprescindível no nível estratégico da organização, devendo, entretanto, ser evitada em outros níveis organizacionais. D A etapa de ação, contemplada no ciclo PDCA, diz respeito à execução primária do ato planejado, dispensando possíveis correções. E Devido a seu caráter incremental, o ciclo PDCA pode contribuir para a obtenção de melhoria organizacional contínua. || JUSTIFICATIVAS: ||A|| - Incorreta. O aspecto cíclico do PDCA existe para garantir que a organização atinja sua excelência de forma gradual, incremental e cíclica. \*/ ||B|| - Incorreta. O teórico propositor do ciclo PDCA foi E. Deming. \*/ ||C|| - Incorreta. O PDCA pode ser aplicado a todos os níveis organizacionais. O nível estratégico, em geral, é incluído de forma prioritária na implementação do PDCA.\*/ ||D|| - Incorreta. A etapa de ação do ciclo PDCA ocupa-se, precisamente, do ato de corrigir ou aprimorar aquilo que vem sendo monitorado.\*/ ||E|| - Correta. Por ser cíclico e incremental, o PDCA pode se tornar importante ferramenta de melhoria contínua.\*/$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,44,$q$Administração Pública$q$,$q$No que concerne à gestão de recursos materiais nas organizações, assinale a opção correta. A A gestão de estoques deve maximizar os investimentos em material estocado, visando à melhoria dos resultados organizacionais. B A gestão de compras deve ser realizada, prioritariamente, de forma terceirizada, principalmente no caso das atividades ligadas ao comércio de mercadorias. C O inventário de estoque deve ser realizado por iniciativa da organização e em período por ela determinado, independentemente dos aspectos legais ou de conformidade. D Os itens classificados como matérias-primas permanecem enquadrados nessa classificação durante toda a cadeia produtiva, necessariamente. E O volume adequado dos níveis de estoque pode variar de acordo com o perfil organizacional e as necessidades sazonais, além de outros fatores conhecidos ou inéditos.$q$,$q$No que concerne à gestão de recursos materiais nas organizações, assinale a opção correta. A A gestão de estoques deve maximizar os investimentos em material estocado, visando à melhoria dos resultados organizacionais. B A gestão de compras deve ser realizada, prioritariamente, de forma terceirizada, principalmente no caso das atividades ligadas ao comércio de mercadorias. C O inventário de estoque deve ser realizado por iniciativa da organização e em período por ela determinado, independentemente dos aspectos legais ou de conformidade. D Os itens classificados como matérias-primas permanecem enquadrados nessa classificação durante toda a cadeia produtiva, necessariamente. E O volume adequado dos níveis de estoque pode variar de acordo com o perfil organizacional e as necessidades sazonais, além de outros fatores conhecidos ou inéditos. || JUSTIFICATIVAS: ||A|| - Incorreta. Devem-se minimizar os investimentos em material estocado, na medida do possível. \*/ ||B|| - Incorreta. Por se tratar de área sensível e de elevado risco, principalmente no âmbito de atividades comerciais, a gestão de compras não deve ser terceirizada, em geral.\*/ ||C|| - Incorreta. Devem ser seguidos, inclusive, os marcos legais e tributários.\*/ ||D|| - Incorreta. A classificação deverá mudar de acordo com o momento de tratativas daquele item ao longo da cadeia produtiva.\*/ ||E|| - Correta. Conforme a operação da gestão de materiais, os volumes considerados adequados para os níveis de estoque sofrerão variação.\*/$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,45,$q$Direito Constitucional$q$,$q$Caso a falta de norma regulamentadora torne inviável o exercício de direitos e liberdades constitucionais, é cabível, segundo a Constituição Federal de 1988 (CF), o ajuizamento de A mandado de segurança individual. B mandado de segurança coletivo. C mandado de injunção. D habeas corpus. E habeas data.$q$,$q$Caso a falta de norma regulamentadora torne inviável o exercício de direitos e liberdades constitucionais, é cabível, segundo a Constituição Federal de 1988 (CF), o ajuizamento de A mandado de segurança individual. B mandado de segurança coletivo. C mandado de injunção. D habeas corpus. E habeas data. || JUSTIFICATIVAS: ||A|| - Incorreta. De acordo com o art. 5.º, LXXI, da CF, “conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania”.\*/ ||B|| - Incorreta. De acordo com o art. 5.º, LXXI, da CF, “conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania”.\*/ ||C|| - Correta. De acordo com o art. 5.º, LXXI, da CF, “conceder- se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania”.\*/ ||D|| - Incorreta. De acordo com o art. 5.º, LXXI, da CF, “conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania”.\*/ ||E|| - Incorreta. De acordo com o art. 5.º, LXXI, da CF, “conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania”.\*/$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,46,$q$Direito Constitucional$q$,$q$Suponha que as seguintes situações tenham ocorrido ao mesmo tempo: a naturalização brasileira de Ana foi cancelada em decorrência de sentença transitada em julgado; Maria foi condenada por improbidade administrativa, nos termos do art. 37, § 4.º, da CF; e Cláudio recusou-se a cumprir obrigação a todos imposta, bem como a cumprir prestação alternativa, em oposição ao que determina o art. 5.º, VIII, da CF. Com base nessa suposição, é correto afirmar que a perda dos direitos políticos se dará em relação a A Ana, Maria e Cláudio. B Maria e Cláudio, apenas. C Cláudio, somente. D Maria, somente. E Ana, somente.$q$,$q$Suponha que as seguintes situações tenham ocorrido ao mesmo tempo: a naturalização brasileira de Ana foi cancelada em decorrência de sentença transitada em julgado; Maria foi condenada por improbidade administrativa, nos termos do art. 37, § 4.º, da CF; e Cláudio recusou-se a cumprir obrigação a todos imposta, bem como a cumprir prestação alternativa, em oposição ao que determina o art. 5.º, VIII, da CF. Com base nessa suposição, é correto afirmar que a perda dos direitos políticos se dará em relação a A Ana, Maria e Cláudio. B Maria e Cláudio, apenas. C Cláudio, somente. D Maria, somente. E Ana, somente. || JUSTIFICATIVAS: ||A|| - Incorreta. Assim dispõe a CF: Art. 15. É vedada a cassação de direitos políticos, cuja perda ou suspensão só se dará nos casos de: I – cancelamento da naturalização por sentença transitada em julgado; II – incapacidade civil absoluta; III – condenação criminal transitada em julgado, enquanto durarem seus efeitos; IV – recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5.º, VIII; V – improbidade administrativa, nos termos do art. 37, § 4.º.\*/ ||B|| - Incorreta. Assim dispõe a CF: Art. 15. É vedada a cassação de direitos políticos, cuja perda ou suspensão só se dará nos casos de: I – cancelamento da naturalização por sentença transitada em julgado; II – incapacidade civil absoluta; III – condenação criminal transitada em julgado, enquanto durarem seus efeitos; IV – recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5.º, VIII; V – improbidade administrativa, nos termos do art. 37, § 4.º.\*/ ||C|| - Incorreta. Assim dispõe a CF: Art. 15. É vedada a cassação de direitos políticos, cuja perda ou suspensão só se dará nos casos de: I – cancelamento da naturalização por sentença transitada em julgado; II – incapacidade civil absoluta; III – condenação criminal transitada em julgado, enquanto durarem seus efeitos; IV – recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5.º, VIII; V – improbidade administrativa, nos termos do art. 37, § 4.º.\*/ ||D|| - Incorreta. Assim dispõe a CF: Art. 15. É vedada a cassação de direitos políticos, cuja perda ou suspensão só se dará nos casos de: I – cancelamento da naturalização por sentença transitada em julgado; II – incapacidade civil absoluta; III – condenação criminal transitada em julgado, enquanto durarem seus efeitos; IV – recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5.º, VIII; V – improbidade administrativa, nos termos do art. 37, § 4.º.\*/ ||E|| - Correta, de acordo com o disposto na CF: Art. 15. É vedada a cassação de direitos políticos, cuja perda ou suspensão só se dará nos casos de: I – cancelamento da naturalização por sentença transitada em julgado; II – incapacidade civil absoluta; III – condenação criminal transitada em julgado, enquanto durarem seus efeitos; IV – recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5.º, VIII; V – improbidade administrativa, nos termos do art. 37, § 4.º.\*/$q$,'X',2,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (PM-DF 2025, CFO, cargo Oficial Policial Militar - 2º Tenente); não é exibido aos estudantes.$q$),
(2025,47,$q$Direito Constitucional$q$,$q$A preservação da ordem pública e a segurança em estabelecimentos penais competem A à polícia militar, apenas. B à polícia penal, apenas. C à polícia militar e à polícia civil, respectivamente. D à polícia civil e à polícia penal, respectivamente. E à polícia militar e à polícia penal, respectivamente.$q$,$q$A preservação da ordem pública e a segurança em estabelecimentos penais competem A à polícia militar, apenas. B à polícia penal, apenas. C à polícia militar e à polícia civil, respectivamente. D à polícia civil e à polícia penal, respectivamente. E à polícia militar e à polícia penal, respectivamente. || JUSTIFICATIVAS: ||A|| - Incorreta. De acordo com o art. 144, § 5.º e § 5.º-A, da CF, “Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública; aos corpos de bombeiros militares, além das atribuições definidas em lei, incumbe a execução de atividades de defesa civil.” Já “às polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe a segurança dos estabelecimentos penais”.\*/ ||B|| - Incorreta. De acordo com o art. 144, § 5.º e § 5.º-A, da CF, “Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública; aos corpos de bombeiros militares, além das atribuições definidas em lei, incumbe a execução de atividades de defesa civil.” Já “às polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe a segurança dos estabelecimentos penais”.\*/ ||C|| - Incorreta. De acordo com o art. 144, § 5.º e § 5.º-A, da CF, “Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública; aos corpos de bombeiros militares, além das atribuições definidas em lei, incumbe a execução de atividades de defesa civil.” Já “às polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe a segurança dos estabelecimentos penais”.\*/ ||D|| - Incorreta. De acordo com o art. 144, § 5.º e § 5.º-A, da CF, “Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública; aos corpos de bombeiros militares, além das atribuições definidas em lei, incumbe a execução de atividades de defesa civil.” Já “às polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe a segurança dos estabelecimentos penais”.\*/ ||E|| - Correta. De acordo com o art. 144, § 5.º e § 5.º-A, da CF, “Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública; aos corpos de bombeiros militares, além das atribuições definidas em lei, incumbe a execução de atividades de defesa civil.” Já “às polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe a segurança dos estabelecimentos penais”.\*/$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2025,48,$q$Direito Constitucional$q$,$q$Conforme previsto no texto constitucional, integra tanto o Conselho da República quanto o Conselho de Defesa Nacional o A ministro das Relações Exteriores. B ministro de Estado da Defesa. C ministro do Planejamento. D ministro da Justiça. E chefe da Casa Civil.$q$,$q$Conforme previsto no texto constitucional, integra tanto o Conselho da República quanto o Conselho de Defesa Nacional o A ministro das Relações Exteriores. B ministro de Estado da Defesa. C ministro do Planejamento. D ministro da Justiça. E chefe da Casa Civil. || JUSTIFICATIVAS: ||A|| - Incorreta. Conforme a CF (art. 89, inciso VI, e art. 91, inciso IV), o ministro da Justiça é o único, entre as opções propostas, que integra ambos os conselhos, o da República e o de Defesa Nacional. \*/ ||B|| - Incorreta. Conforme a CF (art. 89, inciso VI, e art. 91, inciso IV), o ministro da Justiça é o único, entre as opções propostas, que integra ambos os conselhos, o da República e o de Defesa Nacional.\*/ ||C|| - Incorreta. Conforme a CF (art. 89, inciso VI, e art. 91, inciso IV), o ministro da Justiça é o único, entre as opções propostas, que integra ambos os conselhos, o da República e o de Defesa Nacional.\*/ ||D|| - Correta. Conforme a CF (art. 89, inciso VI, e art. 91, inciso IV), o ministro da Justiça é o único, entre as opções propostas, que integra ambos os conselhos, o da República e o de Defesa Nacional.\*/ ||E|| - Incorreta. Conforme a CF (art. 89, inciso VI, e art. 91, inciso IV), o ministro da Justiça é o único, entre as opções propostas, que integra ambos os conselhos, o da República e o de Defesa Nacional.\*/$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim da PROVA OBJETIVA (P1/P2) E GABARITO PRELIMINAR COM JUSTIFICATIVAS (PM-DF 2025, Edital nº 03/2025-DGP/PMDF, CFO, cargo Oficial Policial Militar - 2º Tenente); gabarito conferido no GABARITO DEFINITIVO oficial. Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão 